--[[
	ASHGROVE HOUSE: one-paste installer for Roblox Studio.
	Generated by ashgrove/tools/build_installer.py from ashgrove/src. Don't
	edit this file; edit the source and run the script again.

	HOW TO USE
	  1. Open your place in Studio (or File > New > Baseplate).
	  2. View > Command Bar.
	  3. Select ALL of this file (Ctrl+A), copy it (Ctrl+C), click in the
	     Command Bar, paste (Ctrl+V) and press Enter.
	  4. Press Play.

	It creates (replacing older copies):
	  ReplicatedStorage.Ashgrove                         shared modules
	  ServerScriptService.Ashgrove                       server Script + modules
	  StarterPlayer.StarterPlayerScripts.AshgroveClient  client LocalScript
	and builds the house as Workspace.AshgroveHouse, removing a template
	Baseplate and SpawnLocation (the Baseplate fills the cellar).
	One Ctrl+Z undoes the whole install.

	Too long for the Command Bar? Use the smaller files in
	ashgrove/installer-parts/ instead: paste part 1, press Enter, then
	part 2, and so on, in order.
]]

local REMOVE_OLD = true
local FINISH = true
local DONE_MESSAGE = "[Ashgrove] Installed. Press Play. (Studio keys: F6 next chapter, F7 keen, F8 refill.)"
local ROOTS = {
	{ service = {"ReplicatedStorage"}, name = "Ashgrove" },
	{ service = {"ServerScriptService"}, name = "Ashgrove" },
	{ service = {"StarterPlayer", "StarterPlayerScripts"}, name = "AshgroveClient" },
}

local FILES = {
	{ service = {"ReplicatedStorage"}, path = {"Ashgrove"}, class = "Folder", source = nil },
	{ service = {"ReplicatedStorage"}, path = {"Ashgrove", "Audio"}, class = "ModuleScript", source = [=[
--[[
	Plays a sound from Config.sounds by key. Empty ids are skipped, so
	every call is safe before audio has been picked.

	Parent the sound to a part or attachment for 3D sound, or to
	SoundService for a flat one. On the server, a sound played in the
	workspace is heard by everyone.
]]

local Debris = game:GetService("Debris")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Config = require(ReplicatedStorage:WaitForChild("Ashgrove"):WaitForChild("Config"))

local Audio = {}

function Audio.id(key: string): string
	return (Config.sounds :: any)[key] or ""
end

function Audio.play(key: string, parent: Instance, volume: number?, maxDistance: number?): Sound?
	local id = Audio.id(key)
	if id == "" then
		return nil
	end
	local sound = Instance.new("Sound")
	sound.Name = key
	sound.SoundId = id
	sound.Volume = volume or 0.6
	sound.RollOffMaxDistance = maxDistance or 120
	sound.Parent = parent
	sound:Play()
	Debris:AddItem(sound, 30)
	return sound
end

-- Looping sound that stays until destroyed.
function Audio.loop(key: string, parent: Instance, volume: number?): Sound?
	local id = Audio.id(key)
	if id == "" then
		return nil
	end
	local sound = Instance.new("Sound")
	sound.Name = key
	sound.SoundId = id
	sound.Volume = volume or 0.5
	sound.Looped = true
	sound.Parent = parent
	sound:Play()
	return sound
end

return Audio
]=] },
