	{ service = {"ServerScriptService"}, path = {"Ashgrove", "Build"}, class = "ModuleScript", source = [=[
--[[
	Build: small part-making helpers shared by House (layout) and Dressing
	(furniture and detail). Everything is anchored and smooth-surfaced.
]]

local Build = {}

function Build.part(parent: Instance, name: string, size: Vector3, cf: CFrame, colour: Color3, material: Enum.Material?): Part
	local p = Instance.new("Part")
	p.Name = name
	p.Anchored = true
	p.Size = size
	p.CFrame = cf
	p.Color = colour
	p.Material = material or Enum.Material.SmoothPlastic
	p.TopSurface = Enum.SurfaceType.Smooth
	p.BottomSurface = Enum.SurfaceType.Smooth
	p.Parent = parent
	return p
end

-- Axis-aligned box from two corners.
function Build.box(parent: Instance, name: string, x1: number, x2: number, y1: number, y2: number, z1: number, z2: number, colour: Color3, material: Enum.Material?): Part
	local size = Vector3.new(math.abs(x2 - x1), math.abs(y2 - y1), math.abs(z2 - z1))
	local centre = Vector3.new((x1 + x2) / 2, (y1 + y2) / 2, (z1 + z2) / 2)
	return Build.part(parent, name, size, CFrame.new(centre), colour, material)
end

-- A vertical cylinder standing on (x, y, z).
function Build.column(parent: Instance, name: string, x: number, y: number, z: number, height: number, diameter: number, colour: Color3, material: Enum.Material?): Part
	local p = Build.part(parent, name, Vector3.new(height, diameter, diameter), CFrame.new(x, y + height / 2, z) * CFrame.Angles(0, 0, math.rad(90)), colour, material)
	p.Shape = Enum.PartType.Cylinder
	return p
end

-- A cylinder between two points (branches, chains, rails).
function Build.rod(parent: Instance, name: string, a: Vector3, b: Vector3, diameter: number, colour: Color3, material: Enum.Material?): Part
	local length = (b - a).Magnitude
	local dir = (b - a).Unit
	-- lookAt can't use "up" as its up vector when the rod is vertical.
	local upVector = if math.abs(dir.Y) > 0.99 then Vector3.xAxis else Vector3.yAxis
	-- Cylinders run along X: aim X along a->b.
	local cf = CFrame.lookAt((a + b) / 2, b, upVector) * CFrame.Angles(0, math.rad(90), 0)
	local p = Build.part(parent, name, Vector3.new(length, diameter, diameter), cf, colour, material)
	p.Shape = Enum.PartType.Cylinder
	return p
end

-- Cosmetic only: no collisions, invisible to raycasts.
function Build.decor(p: BasePart): BasePart
	p.CanCollide = false
	p.CanQuery = false
	p.CanTouch = false
	return p
end

function Build.invisible(p: BasePart): BasePart
	p.Transparency = 1
	p.CanCollide = false
	p.CanQuery = false
	p.CanTouch = false
	return p
end

function Build.folder(parent: Instance, name: string): Folder
	local existing = parent:FindFirstChild(name)
	if existing and existing:IsA("Folder") then
		return existing
	end
	local f = Instance.new("Folder")
	f.Name = name
	f.Parent = parent
	return f
end

function Build.attributes(inst: Instance, attrs: { [string]: any }?)
	if attrs then
		for k, v in attrs do
			inst:SetAttribute(k, v)
		end
	end
end

function Build.label(p: BasePart, text: string, face: Enum.NormalId, colour: Color3?, font: Enum.Font?)
	local gui = Instance.new("SurfaceGui")
	gui.Face = face
	gui.SizingMode = Enum.SurfaceGuiSizingMode.PixelsPerStud
	gui.PixelsPerStud = 40
	gui.LightInfluence = 1
	local t = Instance.new("TextLabel")
	t.Size = UDim2.fromScale(1, 1)
	t.BackgroundTransparency = 1
	t.Text = text
	t.TextScaled = true
	t.Font = font or Enum.Font.Garamond
	t.TextColor3 = colour or Color3.fromRGB(218, 210, 188)
	t.Parent = gui
	gui.Parent = p
end

export type Rng = {
	number: (self: Rng, min: number, max: number) -> number,
	integer: (self: Rng, min: number, max: number) -> number,
}

-- Deterministic random numbers, so the dressing comes out the same every
-- build (nothing jumps around between edits). A small LCG, so it runs the
-- same outside Roblox too (the offline checks).
function Build.random(seed: number): Rng
	local state = seed % 2147483647
	if state <= 0 then
		state += 2147483646
	end
	local function nextUnit(): number
		state = (state * 48271) % 2147483647
		return state / 2147483647
	end
	return {
		number = function(_self, min: number, max: number): number
			return min + (max - min) * nextUnit()
		end,
		integer = function(_self, min: number, max: number): number
			return math.min(max, min + math.floor((max - min + 1) * nextUnit()))
		end,
	} :: any
end

return Build
]=] },
	{ service = {"ServerScriptService"}, path = {"Ashgrove", "Crew"}, class = "ModuleScript", source = [=[
--[[
	Crew: the players. Hits, going down, being revived, being taken by the
	Banshee, party wipes, movement modes and their noise, the flashlight,
	the gold ward, and "committed" actions.

	Health is ours, not the Humanoid's: Config.player.hitsToDown hits put a
	player down, a crewmate revives them, and when nobody is left standing
	the party wipes back to the last checkpoint (Director handles that via
	Crew.wiped).

	A committed action (securing an object, a rite step, a revive) roots the
	player and puts their gun away for its length. The player can't cancel
	it; a hit can.

	Player attributes the client reads: Hits, Downed, Taken, MoveMode,
	Flashlight, LightOn, Battery, HasGold, WardRaised, WardReadyAt,
	CommitLabel, CommitEnds, CommitLength.
]]

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Shared = ReplicatedStorage:WaitForChild("Ashgrove")
local Audio = require(Shared:WaitForChild("Audio"))
local Config = require(Shared:WaitForChild("Config"))
local Net = require(Shared:WaitForChild("Net"))
local Signal = require(Shared:WaitForChild("Signal"))

local Map = require(script.Parent.Map)
local Noise = require(script.Parent.Noise)
local Say = require(script.Parent.Say)

local Crew = {}

Crew.wiped = Signal.new()
Crew.characterReady = Signal.new() -- (player, character)
Crew.goldLost = Signal.new()

-- Director sets this so every (re)spawn lands at the current checkpoint.
Crew.spawnCFrame = function(_player: Player): CFrame?
	return nil
end

type Commit = { label: string, token: {}, onCancel: (() -> ())? }

type State = {
	hits: number,
	downed: boolean,
	taken: boolean,
	mode: string,
	flashlightOn: boolean,
	suppressUntil: number,
	battery: number,
	aim: Vector3,
	hasGold: boolean,
	wardUntil: number,
	wardReadyAt: number,
	commit: Commit?,
	invulnUntil: number,
	lastRegen: number,
	hipHeight: number,
	light: SpotLight?,
	lightAttachment: Attachment?,
	revivePrompt: ProximityPrompt?,
	goldPart: BasePart?,
}

local states: { [Player]: State } = {}
local wiping = false

local function newState(): State
	return {
		hits = 0,
		downed = false,
		taken = false,
		mode = "walk",
		flashlightOn = false,
		suppressUntil = 0,
		battery = Config.flashlight.battery,
		aim = Vector3.new(0, 0, -1),
		hasGold = false,
		wardUntil = 0,
		wardReadyAt = 0,
		commit = nil,
		invulnUntil = 0,
		lastRegen = 0,
		hipHeight = 2,
	}
end

function Crew.state(player: Player): State?
	return states[player]
end

function Crew.root(player: Player): BasePart?
	local character = player.Character
	return character and character:FindFirstChild("HumanoidRootPart") :: BasePart?
end

function Crew.head(player: Player): BasePart?
	local character = player.Character
	return character and character:FindFirstChild("Head") :: BasePart?
end

local function humanoidOf(player: Player): Humanoid?
	local character = player.Character
	return character and character:FindFirstChildOfClass("Humanoid")
end

-- Standing, in the game, and able to act.
function Crew.isActive(player: Player): boolean
	local s = states[player]
	if not s or s.downed or s.taken then
		return false
	end
	local humanoid = humanoidOf(player)
	return humanoid ~= nil and humanoid.Health > 0 and Crew.root(player) ~= nil
end

-- What entities may go after: active and not inside a sanctuary.
function Crew.isTargetable(player: Player): boolean
	if not Crew.isActive(player) then
		return false
	end
	local root = Crew.root(player)
	return root ~= nil and not Map.isSanctuary(root.Position)
end

function Crew.activePlayers(): { Player }
	local out = {}
	for player in states do
		if Crew.isActive(player) then
			table.insert(out, player)
		end
	end
	return out
end

-- Active players whose character is inside a wing.
function Crew.playersInWing(wing: string, includeDowned: boolean?): { Player }
	local out = {}
	for player, s in states do
		local root = Crew.root(player)
		if root and not s.taken and (includeDowned or Crew.isActive(player)) and Map.wingAt(root.Position) == wing then
			table.insert(out, player)
		end
	end
	return out
end

function Crew.isCommitting(player: Player): boolean
	local s = states[player]
	return s ~= nil and s.commit ~= nil
end

------------------------------------------------------------------ movement

local function refreshSpeed(player: Player)
	local s = states[player]
	local humanoid = humanoidOf(player)
	if not s or not humanoid then
		return
	end
	local p = Config.player
	local speed
	if s.taken or s.commit then
		speed = 0
	elseif s.downed then
		speed = p.downedSpeed
	elseif s.mode == "sprint" then
		speed = p.sprintSpeed
	elseif s.mode == "crouch" then
		speed = p.crouchSpeed
	else
		speed = p.walkSpeed
	end
	humanoid.WalkSpeed = speed
	-- Down, taken or busy: hands are full, so your gun is put away.
	if s.downed or s.taken or s.commit then
		humanoid:UnequipTools()
	end
	humanoid.UseJumpPower = true
	humanoid.JumpPower = if s.downed or s.commit or s.taken then 0 else p.jumpPower
	humanoid.HipHeight = if s.downed then math.max(0.2, s.hipHeight - 1.2) else s.hipHeight
end

------------------------------------------------------------------ flashlight

local function lightOn(s: State): boolean
	return s.flashlightOn and s.battery > 0 and os.clock() >= s.suppressUntil and not s.taken
end

local function updateLight(player: Player)
	local s = states[player]
	if not s then
		return
	end
	local on = lightOn(s)
	if s.light then
		s.light.Enabled = on
	end
	player:SetAttribute("Flashlight", s.flashlightOn)
	player:SetAttribute("LightOn", on)
	player:SetAttribute("Battery", math.floor(s.battery + 0.5))
end

-- Forces the light off for a while (reloading needs both hands).
function Crew.suppressFlashlight(player: Player, seconds: number)
	local s = states[player]
	if not s then
		return
	end
	s.suppressUntil = math.max(s.suppressUntil, os.clock() + seconds)
	updateLight(player)
	task.delay(seconds + 0.05, updateLight, player)
end

function Crew.addBattery(player: Player, amount: number): boolean
	local s = states[player]
	if not s or s.battery >= Config.flashlight.maxBattery - 1 then
		return false
	end
	s.battery = math.min(Config.flashlight.maxBattery, s.battery + amount)
	updateLight(player)
	return true
end

-- Every flashlight currently shining: where from and which way.
function Crew.flashlights(): { { player: Player, origin: Vector3, direction: Vector3 } }
	local out = {}
	for player, s in states do
		if lightOn(s) then
			local head = Crew.head(player)
			if head then
				table.insert(out, { player = player, origin = head.Position, direction = s.aim })
			end
		end
	end
	return out
end

function Crew.aim(player: Player): Vector3
	local s = states[player]
	return if s then s.aim else Vector3.new(0, 0, -1)
end

------------------------------------------------------------------ ward

function Crew.giveGold(player: Player)
	local s = states[player]
	if s then
		s.hasGold = true
		player:SetAttribute("HasGold", true)
		Say.to(player, "Cornelius's gold sovereign. [G] raises it.", 5, "hint")
	end
end

function Crew.isWardRaised(player: Player): boolean
	local s = states[player]
	return s ~= nil and os.clock() < s.wardUntil and Crew.isActive(player)
end

local function raiseWard(player: Player)
	local s = states[player]
	if not s or not s.hasGold or not Crew.isActive(player) then
		return
	end
	local now = os.clock()
	if now < s.wardReadyAt then
		return
	end
	s.wardReadyAt = now + Config.ward.cooldown
	s.wardUntil = now + Config.ward.raiseTime
	player:SetAttribute("WardRaised", true)
	player:SetAttribute("WardReadyAt", workspace:GetServerTimeNow() + Config.ward.cooldown)
	if s.goldPart then
		s.goldPart.Transparency = 0
	end
	task.delay(Config.ward.raiseTime, function()
		player:SetAttribute("WardRaised", false)
		if s.goldPart then
			s.goldPart.Transparency = 1
		end
	end)
end

------------------------------------------------------------------ commit

local function clearCommitAttributes(player: Player)
	player:SetAttribute("CommitLabel", nil)
	player:SetAttribute("CommitEnds", nil)
	player:SetAttribute("CommitLength", nil)
end

-- Starts a committed action. Returns false if the player can't commit
-- right now (already busy, down, taken).
function Crew.commit(player: Player, seconds: number, label: string, onDone: () -> (), onCancel: (() -> ())?): boolean
	local s = states[player]
	if not s or not Crew.isActive(player) or s.commit then
		return false
	end
	local token = {}
	s.commit = { label = label, token = token, onCancel = onCancel }
	player:SetAttribute("CommitLabel", label)
	player:SetAttribute("CommitEnds", workspace:GetServerTimeNow() + seconds)
	player:SetAttribute("CommitLength", seconds)
	refreshSpeed(player)
	task.delay(seconds, function()
		local current = s.commit
		if current and current.token == token then
			s.commit = nil
			clearCommitAttributes(player)
			refreshSpeed(player)
			onDone()
		end
	end)
	return true
end

function Crew.cancelCommit(player: Player)
	local s = states[player]
	local current = s and s.commit
	if not s or not current then
		return
	end
	s.commit = nil
	clearCommitAttributes(player)
	refreshSpeed(player)
	Say.to(player, "Interrupted.", 2, "hint")
	if current.onCancel then
		task.spawn(current.onCancel)
	end
end

------------------------------------------------------------------ hits, down, taken

local function checkWipe()
	if wiping then
		return
	end
	local anyone, anyActive = false, false
	for player in states do
		if player.Parent and player.Character then
			anyone = true
			if Crew.isActive(player) then
				anyActive = true
			end
		end
	end
	if anyone and not anyActive then
		wiping = true
		Crew.wiped:Fire()
	end
end

local function setRevivePrompt(player: Player, enabled: boolean)
	local s = states[player]
	if s and s.revivePrompt then
		s.revivePrompt.Enabled = enabled
	end
end

function Crew.down(player: Player)
	local s = states[player]
	if not s or s.downed or s.taken then
		return
	end
	s.downed = true
	Crew.cancelCommit(player)
	player:SetAttribute("Downed", true)
	refreshSpeed(player)
	setRevivePrompt(player, true)
	Say.to(player, "You're down. A crewmate can get you up.", 6, "story")
	Say.except(player, `{player.DisplayName} is down. Get to them.`, 5, "story")
	checkWipe()
end

function Crew.revive(player: Player)
	local s = states[player]
	if not s or not s.downed or s.taken then
		return
	end
	s.downed = false
	s.hits = Config.player.hitsToDown - 1
	s.invulnUntil = os.clock() + 2
	player:SetAttribute("Downed", false)
	player:SetAttribute("Hits", s.hits)
	setRevivePrompt(player, false)
	refreshSpeed(player)
	Say.all(`{player.DisplayName} is back on their feet.`, 3, "story")
end

function Crew.hit(player: Player, amount: number)
	local s = states[player]
	if not s or not Crew.isActive(player) then
		return
	end
	local now = os.clock()
	if now < s.invulnUntil then
		return
	end
	s.invulnUntil = now + Config.player.hitInvulnerability
	s.hits = math.min(s.hits + amount, Config.player.hitsToDown)
	player:SetAttribute("Hits", s.hits)
	local root = Crew.root(player)
	if root then
		Audio.play("hurt", root, 0.7)
	end
	Crew.cancelCommit(player)
	if s.hits >= Config.player.hitsToDown then
		Crew.down(player)
	end
end

-- Taken by the Banshee: out of the game until the party reaches a
-- sanctuary. Can't be revived in place.
function Crew.take(player: Player)
	local s = states[player]
	if not s or s.taken then
		return
	end
	Crew.cancelCommit(player)
	s.taken = true
	s.downed = false
	player:SetAttribute("Taken", true)
	player:SetAttribute("Downed", false)
	setRevivePrompt(player, false)
	updateLight(player)
	refreshSpeed(player)
	local character = player.Character
	local root = Crew.root(player)
	if character and root then
		root.Anchored = true
		character:PivotTo(CFrame.new(Config.player.takenHoldPosition))
	end
	Net.event("Spectate"):FireClient(player, true)
	Say.except(player, `{player.DisplayName} is gone. Get somewhere safe and they'll come back.`, 6, "story")
	checkWipe()
end

local function placeCharacter(player: Player, cf: CFrame)
	local character = player.Character
	local root = Crew.root(player)
	if character and root then
		root.Anchored = false
		character:PivotTo(cf)
		root.AssemblyLinearVelocity = Vector3.zero
	end
end

function Crew.restoreTaken(at: CFrame)
	local i = 0
	for player, s in states do
		if s.taken then
			i += 1
			s.taken = false
			s.hits = 0
			player:SetAttribute("Taken", false)
			player:SetAttribute("Hits", 0)
			placeCharacter(player, at * CFrame.new(2 * i, 0, 2))
			refreshSpeed(player)
			updateLight(player)
			Net.event("Spectate"):FireClient(player, false)
			Say.all(`{player.DisplayName} stumbles back in out of the dark.`, 4, "story")
		end
	end
end

-- Checkpoint reset after a wipe.
function Crew.resetAll(at: CFrame)
	local i = 0
	for player, s in states do
		s.commit = nil
		clearCommitAttributes(player)
		s.hits = 0
		s.downed = false
		s.taken = false
		s.suppressUntil = 0
		s.invulnUntil = os.clock() + 3
		player:SetAttribute("Hits", 0)
		player:SetAttribute("Downed", false)
		player:SetAttribute("Taken", false)
		setRevivePrompt(player, false)
		placeCharacter(player, at * CFrame.new((i % 4) * 3 - 4.5, 0, math.floor(i / 4) * 3))
		refreshSpeed(player)
		updateLight(player)
		Net.event("Spectate"):FireClient(player, false)
		i += 1
	end
	wiping = false
end

------------------------------------------------------------------ characters

local function onCharacter(player: Player, character: Model)
	local s = states[player]
	if not s then
		return
	end
	s.hits = 0
	s.downed = false
	s.taken = false
	s.commit = nil
	clearCommitAttributes(player)
	player:SetAttribute("Hits", 0)
	player:SetAttribute("Downed", false)
	player:SetAttribute("Taken", false)

	local humanoid = character:WaitForChild("Humanoid") :: Humanoid
	local root = character:WaitForChild("HumanoidRootPart") :: BasePart
	local head = character:WaitForChild("Head") :: BasePart
	s.hipHeight = humanoid.HipHeight
	humanoid.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None

	local attachment = Instance.new("Attachment")
	attachment.Name = "AshFlashlight"
	attachment.Position = Vector3.new(0, 0.2, -0.6)
	attachment.Parent = head
	local light = Instance.new("SpotLight")
	light.Name = "AshFlashlight"
	light.Angle = Config.flashlight.angle
	light.Range = Config.flashlight.range
	light.Brightness = Config.flashlight.brightness
	light.Color = Color3.fromRGB(255, 240, 220)
	light.Shadows = true
	light.Face = Enum.NormalId.Front
	light.Enabled = false
	light.Parent = attachment
	s.light = light
	s.lightAttachment = attachment

	local prompt = Instance.new("ProximityPrompt")
	prompt.Name = "Revive"
	prompt.ActionText = "Revive"
	prompt.ObjectText = player.DisplayName
	prompt.HoldDuration = 0.2
	prompt.MaxActivationDistance = 8
	prompt.RequiresLineOfSight = false
	prompt.Enabled = false
	prompt.Parent = root
	prompt.Triggered:Connect(function(rescuer: Player)
		if rescuer == player or not s.downed or s.taken then
			return
		end
		Crew.commit(rescuer, Config.commit.revive, `Getting {player.DisplayName} up`, function()
			Crew.revive(player)
		end)
	end)
	s.revivePrompt = prompt

	local gold = Instance.new("Part")
	gold.Name = "RaisedGold"
	gold.Shape = Enum.PartType.Ball
	gold.Size = Vector3.one * 0.6
	gold.Color = Color3.fromRGB(214, 172, 60)
	gold.Material = Enum.Material.Metal
	gold.CanCollide = false
	gold.CanQuery = false
	gold.Massless = true
	gold.Transparency = 1
	local weld = Instance.new("Weld")
	weld.Part0 = head
	weld.Part1 = gold
	weld.C0 = CFrame.new(-0.8, -0.2, -1.6)
	weld.Parent = gold
	gold.Parent = character
	s.goldPart = gold

	refreshSpeed(player)
	updateLight(player)

	character.ChildAdded:Connect(function(child)
		if child:IsA("Tool") and (s.downed or s.taken or s.commit) then
			task.defer(function()
				humanoid:UnequipTools()
			end)
		end
	end)

	task.spawn(function()
		if not character.Parent then
			character.AncestryChanged:Wait()
		end
		task.wait()
		local cf = Crew.spawnCFrame(player)
		if cf then
			character:PivotTo(cf)
		end
	end)
	Crew.characterReady:Fire(player, character)
end

local function onPlayer(player: Player)
	states[player] = newState()
	player.CameraMode = Enum.CameraMode.LockFirstPerson
	player.CameraMaxZoomDistance = 0.5
	player:SetAttribute("MoveMode", "walk")
	player:SetAttribute("HasGold", false)
	player:SetAttribute("Battery", Config.flashlight.battery)
	player.CharacterAdded:Connect(function(character)
		onCharacter(player, character)
	end)
	if player.Character then
		task.spawn(onCharacter, player, player.Character)
	end
end

------------------------------------------------------------------ start

function Crew.start()
	Net.event("Move").OnServerEvent:Connect(function(player, mode)
		local s = states[player]
		if s and (mode == "walk" or mode == "sprint" or mode == "crouch") then
			s.mode = mode
			player:SetAttribute("MoveMode", mode)
			refreshSpeed(player)
		end
	end)

	Net.event("Flashlight").OnServerEvent:Connect(function(player, on)
		local s = states[player]
		if s and typeof(on) == "boolean" then
			s.flashlightOn = on
			updateLight(player)
		end
	end)

	Net.unreliable("Aim").OnServerEvent:Connect(function(player, direction)
		local s = states[player]
		if not s or typeof(direction) ~= "Vector3" or direction.Magnitude < 0.5 or direction.Magnitude ~= direction.Magnitude then
			return
		end
		s.aim = direction.Unit
		local head = Crew.head(player)
		if head and s.lightAttachment then
			local rel = head.CFrame:VectorToObjectSpace(s.aim)
			local origin = Vector3.new(0, 0.2, -0.6)
			s.lightAttachment.CFrame = CFrame.lookAt(origin, origin + rel)
		end
	end)

	Net.event("Ward").OnServerEvent:Connect(raiseWard)

	Players.PlayerAdded:Connect(onPlayer)
	for _, player in Players:GetPlayers() do
		onPlayer(player)
	end
	Players.PlayerRemoving:Connect(function(player)
		local s = states[player]
		states[player] = nil
		if s and s.hasGold then
			Crew.goldLost:Fire()
		end
		task.defer(checkWipe)
	end)

	-- Footstep noise.
	task.spawn(function()
		local n = Config.player.noise
		while true do
			task.wait(n.sampleEvery)
			for player, s in states do
				local root = Crew.root(player)
				if root and Crew.isActive(player) then
					local v = root.AssemblyLinearVelocity
					local speed = Vector3.new(v.X, 0, v.Z).Magnitude
					if speed > 2 then
						local radius = if s.mode == "sprint" and speed > Config.player.walkSpeed + 2
							then n.sprint
							elseif s.mode == "crouch" then n.crouch
							else n.walk
						Noise.emit(root.Position, radius, "footsteps", player)
					end
				end
			end
		end
	end)

	-- Battery, regeneration in sanctuaries, taken players coming back.
	task.spawn(function()
		local last = os.clock()
		while true do
			task.wait(0.5)
			local now = os.clock()
			local dt = now - last
			last = now
			local safeRoot: BasePart? = nil
			local anyTaken = false
			for player, s in states do
				if lightOn(s) then
					s.battery = math.max(0, s.battery - dt)
					if s.battery <= 0 then
						s.flashlightOn = false
						Say.to(player, "Your torch is dead. Find batteries.", 4, "hint")
					end
					updateLight(player)
				end
				if s.taken then
					anyTaken = true
				end
				local root = Crew.root(player)
				if root and Crew.isActive(player) and Map.isSanctuary(root.Position) then
					safeRoot = root
					if s.hits > 0 and now - s.lastRegen >= Config.player.sanctuaryRegenEvery then
						s.lastRegen = now
						s.hits -= 1
						player:SetAttribute("Hits", s.hits)
					end
				else
					s.lastRegen = now
				end
			end
			if anyTaken and safeRoot then
				Crew.restoreTaken(safeRoot.CFrame)
			end
			checkWipe()
		end
	end)
end

return Crew
]=] },
	{ service = {"ServerScriptService"}, path = {"Ashgrove", "Director"}, class = "ModuleScript", source = [=[
--[[
	Director: Story 1, start to finish. Chapters, objectives, checkpoints,
	story beats and party wipes. Everything else reacts to the systems; this
	is the only file that knows the story's order.

	  I    The Second Crew      van -> hall. Find the camp and the manifest.
	  II   The Portrait Gallery the Dullahan. Secure the spine whip.
	                            First distant keen.
	  III  The Servants' Wing   the Lamp-shy. She mourns in the kitchen;
	                            the first keen. Secure the hollow lantern.
	                            The storm cuts the hall's power.
	  IV   The Cellar Vault     the opened box. Her keen with nothing to
	                            kill. Back to the van; she keeps keening.

	Checkpoints are the chapter starts. A wipe puts everyone back at the
	last one with the ammo they had there.
]]

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")

local Shared = ReplicatedStorage:WaitForChild("Ashgrove")
local Config = require(Shared:WaitForChild("Config"))
local Net = require(Shared:WaitForChild("Net"))

local Ashgrove = script.Parent
local Banshee = require(Ashgrove.Banshee)
local BellBoard = require(Ashgrove.BellBoard)
local Crew = require(Ashgrove.Crew)
local Doors = require(Ashgrove.Doors)
local Map = require(Ashgrove.Map)
local Models = require(Ashgrove.Models)
local Pickups = require(Ashgrove.Pickups)
local Reading = require(Ashgrove.Reading)
local Retrieval = require(Ashgrove.Retrieval)
local Rites = require(Ashgrove.Rites)
local Say = require(Ashgrove.Say)
local Shots = require(Ashgrove.Shots)
local Storm = require(Ashgrove.Storm)
local Entity = require(Ashgrove.Entities.Entity)
local Registry = require(Ashgrove.Entities.Registry)
local DullahanBehaviour = require(Ashgrove.Entities.Dullahan)
local LampshyBehaviour = require(Ashgrove.Entities.Lampshy)

local Director = {}

type Objective = { text: string, done: boolean? }

local chapter = 0
local chapterStartedAt = 0
local checkpointName = "Spawn_Van"
local objectives: { Objective } = {}
local flags: { [string]: any } = {}
local wiping = false

local dullahan
local lampshy

local function anyoneIn(wing: string): boolean
	return #Crew.playersInWing(wing) > 0
end

local function anyoneInRoom(room: string): boolean
	for _, player in Crew.activePlayers() do
		local root = Crew.root(player)
		if root and Map.roomAt(root.Position) == room then
			return true
		end
	end
	return false
end

local function setObjectives(list: { Objective })
	objectives = list
	Net.event("Objectives"):FireAllClients(objectives)
end

local function tick(index: number)
	if objectives[index] and not objectives[index].done then
		objectives[index].done = true
		Net.event("Objectives"):FireAllClients(objectives)
	end
end

local function setCheckpoint(name: string)
	checkpointName = name
end

local function card(title: string, subtitle: string)
	Net.event("Chapter"):FireAllClients(title, subtitle)
end

------------------------------------------------------------------ chapters

local enterChapter: (number) -> ()

local function chapterOne()
	setCheckpoint("Spawn_Van")
	card("I. The Second Crew", "Ashgrove House. One night. A storm off the sea.")
	setObjectives({
		{ text = "Go into Ashgrove House" },
		{ text = "Find the first crew's camp in the hall" },
	})
	task.delay(4, function()
		Say.all("Shift sprint, C crouch, F torch, G raise gold, E interact, H help.", 10, "hint")
	end)
end

local function chapterTwo()
	setCheckpoint("Spawn_HallCamp")
	Pickups.roll()
	dullahan:activate()
	card("II. The Portrait Gallery", "Lot 114. The spine whip.")
	setObjectives({
		{ text = "Secure Lot 114, the spine whip (far end of the portrait gallery)" },
		{ text = "Optional: take Cornelius's gold sovereign (case in the hall)" },
	})
end

local function chapterThree()
	setCheckpoint("Spawn_HallCamp")
	Doors.setLocked("ServantsDoor", false)
	Say.all("Okafor's keys were in the tack case. The servants' door is open.", 5, "story")
	lampshy:activate()
	card("III. The Servants' Wing", "Lot 203. The hollow lantern.")
	setObjectives({
		{ text = "Secure Lot 203, the hollow lantern (scullery, servants' wing)" },
		{ text = "Lot 077, the silver comb, is missing. Leave it." },
	})
end

local function chapterFour()
	setCheckpoint("Spawn_Stairwell")
	Doors.setLocked("VaultGate", false)
	Banshee.setNatural(false)
	Say.all("The chain on the cellar gate has rusted through. The way down is open.", 5, "story")
	card("IV. The Cellar Vault", "Lot 001. The sealed box.")
	setObjectives({
		{ text = "Find Lot 001, the sealed box (cellar vault)" },
	})
end

local CHAPTERS = { chapterOne, chapterTwo, chapterThree, chapterFour }

enterChapter = function(n: number)
	if n <= chapter or not CHAPTERS[n] then
		return
	end
	chapter = n
	chapterStartedAt = os.clock()
	CHAPTERS[n]()
end

local function ending()
	if flags.ended then
		return
	end
	flags.ended = true
	setObjectives({ { text = "You got out.", done = true } })
	for _, e in Registry.all() do
		e:retire()
	end
	local door = CFrame.lookAt(Vector3.new(-64, 0, 0), Vector3.new(-130, 0, 0))
	Banshee.ending(door)
	Say.all("[The keening doesn't stop]", 4, "sound")
	task.wait(4)
	Say.all("You're out in the rain, and she's still keening.", 5, "story")
	task.wait(5)
	Say.all("It wasn't about you.", 5, "story")
	task.wait(4)
	-- The first crew's dead van, behind you.
	local lights = Map.root():FindFirstChild("CrewOneHeadlights", true)
	local beam = lights and lights:FindFirstChildOfClass("SpotLight")
	if lights and beam and lights:IsA("BasePart") then
		lights.Material = Enum.Material.Neon
		beam.Enabled = true
		Say.all("[Behind you, the first crew's van flashes its headlights once]", 4, "sound")
		task.wait(0.6)
		beam.Enabled = false
		lights.Material = Enum.Material.Glass
	end
	task.wait(4)
	Net.event("Screen"):FireAllClients("end", "END OF STORY 1\n\nThe box was empty.\nSomebody is wearing what was in it.")
end

------------------------------------------------------------------ story beats

local function onSecured(objectId: string)
	if objectId == "SpineWhip" then
		tick(1)
		Storm.escalate()
		enterChapter(3)
	elseif objectId == "HollowLantern" then
		tick(1)
		Storm.escalate()
		enterChapter(4)
	end
end

local function onInspected(objectId: string, player: Player)
	if objectId ~= "DybbukBox" then
		return
	end
	tick(1)
	Say.all("The seal is broken. The box is empty.", 5, "story")
	task.wait(Config.story.ruleBreakDelay)
	if flags.ended then
		return
	end
	-- The rule-break: she keens with nothing here to kill. It's for one of you.
	local target = if table.find(Crew.playersInWing("Vault"), player) then player else nil
	if Banshee.keen("Vault", { forced = true, target = target }) then
		flags.ruleBreak = true
		setObjectives({ { text = "Nothing down here can die in your place. Keep the custom, or get out." } })
	else
		flags.finale = true
		setObjectives({ { text = "Get everyone back to the van" } })
	end
end

local function onKeenEnded(wing: string, _outcome: string)
	if chapter == 3 and wing == "ServantsWing" and not flags.naturalOn then
		flags.naturalOn = true
		Banshee.setNatural(true)
	end
	if flags.ruleBreak and wing == "Vault" and not flags.finale then
		flags.finale = true
		setObjectives({ { text = "Get everyone back to the van" } })
	end
end

local function storyLoop()
	while not flags.ended do
		task.wait(0.5)
		local now = os.clock()
		if chapter == 1 then
			if anyoneIn("Hall") then
				tick(1)
			end
			if anyoneIn("Gallery") then
				enterChapter(2)
			end
		elseif chapter == 2 then
			if not flags.distant and now - chapterStartedAt >= Config.story.firstDistantDelay then
				flags.distant = true
				Banshee.enableDistant()
				Banshee.distantNow()
			end
		elseif chapter == 3 then
			if not flags.distant then
				flags.distant = true
				Banshee.enableDistant()
			end
			if not flags.kitchenMourning and anyoneInRoom("Kitchen") then
				flags.kitchenMourning = true
				task.delay(Config.story.kitchenMourningDelay, function()
					if not Banshee.mourn(Map.marker("Body_Kitchen").Position, { noteId = "Memo_Kitchen", key = "Kitchen", grace = 6 }) then
						Reading.reveal("Memo_Kitchen")
						flags.firstKeenAt = os.clock() + Config.story.firstKeenDelay
					end
				end)
			end
			if flags.firstKeenAt and not flags.firstKeen and now >= flags.firstKeenAt and anyoneIn("ServantsWing") then
				if Banshee.keen("ServantsWing", { forced = true }) then
					flags.firstKeen = true
				end
			end
		elseif chapter == 4 then
			if flags.finale then
				local everyone = true
				local anyone = false
				for _, player in Players:GetPlayers() do
					local s = Crew.state(player)
					if s and not s.taken then
						anyone = true
						local root = Crew.root(player)
						if not Crew.isActive(player) or not root or Map.wingAt(root.Position) ~= "Van" then
							everyone = false
						end
					end
				end
				if anyone and everyone then
					task.spawn(ending)
				end
			end
		end
	end
end

------------------------------------------------------------------ wipes

local function onWipe()
	if wiping or flags.ended then
		return
	end
	wiping = true
	Net.event("Screen"):FireAllClients("wipe", "The house keeps you.")
	task.wait(3)
	Banshee.reset()
	for _, e in Registry.all() do
		e:reset()
	end
	Doors.clearLockouts()
	Crew.resetAll(Map.marker(checkpointName).CFrame)
	if flags.ruleBreak and not flags.finale then
		-- The vault keen is lost with the wipe; go straight to the escape.
		flags.finale = true
		setObjectives({ { text = "Get everyone back to the van" } })
	end
	Net.event("Screen"):FireAllClients("clear", "")
	Say.all("Back to the last safe place.", 4, "story")
	wiping = false
end

------------------------------------------------------------------ debug

local function onDebug(player: Player, command: any)
	if not RunService:IsStudio() or not Config.debug.studioKeys then
		return
	end
	if command == "next" then
		if chapter == 1 then
			enterChapter(2)
		elseif chapter == 2 then
			Retrieval.forceSecure("SpineWhip")
		elseif chapter == 3 then
			Retrieval.forceSecure("HollowLantern")
		end
		Say.to(player, `[debug] chapter {chapter}`, 3, "hint")
	elseif command == "keen" then
		local root = Crew.root(player)
		local wing = root and Map.wingAt(root.Position)
		if not wing or not Banshee.keen(wing, { forced = true, target = player }) then
			Say.to(player, "[debug] can't keen here (hall, van and grounds never keen)", 3, "hint")
		end
	elseif command == "refill" then
		Crew.addBattery(player, Config.flashlight.maxBattery)
		Say.to(player, "[debug] torch refilled", 2, "hint")
	end
end

------------------------------------------------------------------ start

function Director.start()
	Map.root()
	Storm.start()
	Doors.setup()
	Rites.setup()
	Reading.setup()
	Retrieval.setup()
	for _, objectId in { "SpineWhip", "HollowLantern", "DybbukBox" } do
		Retrieval.setEnabled(objectId, true)
	end

	Crew.spawnCFrame = function()
		return Map.marker(checkpointName).CFrame
	end
	Models.collect()
	Shots.start()
	Crew.start()
	Pickups.setup()

	dullahan = Entity.new("Dullahan", Config.entities.Dullahan, DullahanBehaviour)
	lampshy = Entity.new("Lampshy", Config.entities.Lampshy, LampshyBehaviour)
	Entity.startLoop()
	Banshee.setup()
	BellBoard.start()

	Retrieval.secured:Connect(onSecured)
	Retrieval.inspected:Connect(onInspected)
	Banshee.keenEnded:Connect(onKeenEnded)
	Banshee.keenStarted:Connect(function(wing: string)
		if chapter == 3 and wing == "ServantsWing" then
			flags.firstKeen = true
		end
	end)
	Banshee.mourningEnded:Connect(function(key: string?, disturbed: boolean)
		if key == "Kitchen" and not disturbed and not flags.firstKeenAt then
			flags.firstKeenAt = os.clock() + Config.story.firstKeenDelay
		end
	end)
	Reading.read:Connect(function(noteId: string)
		if noteId == "Manifest" and chapter == 1 then
			tick(2)
		end
	end)
	Crew.wiped:Connect(onWipe)
	Net.event("Debug").OnServerEvent:Connect(onDebug)

	Players.PlayerAdded:Connect(function(player)
		task.delay(2, function()
			Net.event("Objectives"):FireClient(player, objectives)
		end)
	end)

	enterChapter(1)
	task.spawn(storyLoop)
end

return Director
]=] },
	{ service = {"ServerScriptService"}, path = {"Ashgrove", "Doors"}, class = "ModuleScript", source = [=[
--[[
	Doors: story locks and the Banshee's lockout.

	A door part has DoorId, Wing (the wing it leads into), StartsLocked and
	LockedText. Locked doors are solid with a prompt that explains why.

	Lockout: fleeing a keen "costs you the wing for now". The wing's doors
	are hung with black cloth and won't open for a while.
]]

local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Config = require(ReplicatedStorage:WaitForChild("Ashgrove"):WaitForChild("Config"))

local Map = require(script.Parent.Map)
local Say = require(script.Parent.Say)

local Doors = {}

type Door = {
	part: BasePart,
	wing: string,
	locked: boolean,
	lockoutUntil: number,
	text: string,
	colour: Color3,
	material: Enum.Material,
	prompt: ProximityPrompt,
}

local doors: { [string]: Door } = {}

local function apply(door: Door)
	local lockedOut = os.clock() < door.lockoutUntil
	local closed = door.locked or lockedOut
	door.part.CanCollide = closed
	door.part.CanQuery = closed
	door.part.Transparency = if closed then 0 else 1
	if lockedOut and not door.locked then
		door.part.Color = Color3.fromRGB(12, 12, 14)
		door.part.Material = Enum.Material.Fabric
		door.prompt.ObjectText = "Black cloth hangs across the doorway"
	else
		door.part.Color = door.colour
		door.part.Material = door.material
		door.prompt.ObjectText = door.text
	end
	door.prompt.Enabled = closed
end

function Doors.setLocked(doorId: string, locked: boolean)
	local door = doors[doorId]
	if door then
		door.locked = locked
		apply(door)
	end
end

function Doors.lockout(wing: string, seconds: number?)
	local duration = seconds or Config.banshee.leaveLockout
	for _, door in doors do
		if door.wing == wing and not door.locked then
			door.lockoutUntil = os.clock() + duration
			apply(door)
			task.delay(duration + 0.1, apply, door)
		end
	end
end

function Doors.clearLockouts()
	for _, door in doors do
		door.lockoutUntil = 0
		apply(door)
	end
end

function Doors.setup()
	for _, p in Map.interact("Doors"):GetChildren() do
		if p:IsA("BasePart") and p:GetAttribute("DoorId") then
			local prompt = Instance.new("ProximityPrompt")
			prompt.ActionText = "Try the door"
			prompt.HoldDuration = 0
			prompt.MaxActivationDistance = 8
			prompt.RequiresLineOfSight = false
			prompt.Parent = p
			local door: Door = {
				part = p,
				wing = p:GetAttribute("Wing") or "",
				locked = p:GetAttribute("StartsLocked") == true,
				lockoutUntil = 0,
				text = p:GetAttribute("LockedText") or "Locked.",
				colour = p.Color,
				material = p.Material,
				prompt = prompt,
			}
			prompt.Triggered:Connect(function(player)
				if door.locked then
					Say.to(player, door.text, 3, "hint")
				elseif os.clock() < door.lockoutUntil then
					Say.to(player, "Black cloth over the doorway. It won't let you back in yet.", 3, "hint")
				end
			end)
			doors[p:GetAttribute("DoorId")] = door
			apply(door)
		end
	end
end

return Doors
]=] },
	{ service = {"ServerScriptService"}, path = {"Ashgrove", "Dressing"}, class = "ModuleScript", source = [=[
--[[
	Dressing: everything that makes the layout look like Ashgrove House.
	Panelled rooms get furniture, the collection gets its cases and crates,
	the house gets an upper storey, roofs with crow-stepped gables and
	chimneys, and the grounds get the drive, the dead trees, the family
	plot, the cliff and a lighthouse out at sea.

	Nothing here is read by the gameplay. Move it, delete it, or replace it
	with the art brief's AH_Prop_* / AH_Kit_* models freely. After big
	changes run tools/check_greybox.luau: it fails if something solid now
	blocks a route, a marker or a pickup.

	Rules this file keeps (so the game still plays):
	  - nothing solid in doorways, on walking routes or on markers
	  - the gallery's sight line (x -8..99 at z -19, eye height) stays open
	  - decorative lights only where no entity cares about light (the
	    hall, the gallery, outside). Gameplay light is Interact/Lamps.
	  - lights with a Flicker attribute ("bulb" | "window") are animated at
	    runtime by Storm; a part with Spin = true is turned (the
	    lighthouse beam)
]]

local Build = require(script.Parent.Build)

local part, box, column, rod, decor = Build.part, Build.box, Build.column, Build.rod, Build.decor

local Dressing = {}

local C = {
	oak = Color3.fromRGB(70, 50, 36),
	oakDark = Color3.fromRGB(48, 34, 26),
	walnut = Color3.fromRGB(60, 40, 30),
	sheet = Color3.fromRGB(194, 188, 174),
	sheetGrey = Color3.fromRGB(150, 146, 136),
	brass = Color3.fromRGB(150, 118, 60),
	iron = Color3.fromRGB(40, 40, 44),
	glass = Color3.fromRGB(110, 128, 146),
	stone = Color3.fromRGB(96, 95, 90),
	stoneDark = Color3.fromRGB(70, 70, 68),
	limestone = Color3.fromRGB(150, 148, 138),
	marbleWhite = Color3.fromRGB(196, 192, 182),
	marbleBlack = Color3.fromRGB(34, 34, 36),
	rugRed = Color3.fromRGB(92, 30, 28),
	rugGreen = Color3.fromRGB(34, 52, 40),
	rugGold = Color3.fromRGB(140, 104, 48),
	fabricBrown = Color3.fromRGB(86, 60, 44),
	fabricGreen = Color3.fromRGB(44, 62, 50),
	crate = Color3.fromRGB(108, 84, 56),
	canvas = Color3.fromRGB(44, 38, 32),
	paper = Color3.fromRGB(218, 210, 188),
	black = Color3.fromRGB(14, 14, 16),
	wax = Color3.fromRGB(220, 210, 180),
	stain = Color3.fromRGB(20, 18, 14),
	web = Color3.fromRGB(220, 220, 214),
	roof = Color3.fromRGB(50, 52, 58),
	bark = Color3.fromRGB(44, 36, 30),
	hedge = Color3.fromRGB(30, 44, 28),
	earth = Color3.fromRGB(46, 36, 28),
	lamp = Color3.fromRGB(255, 214, 160),
	white = Color3.fromRGB(214, 214, 206),
	red = Color3.fromRGB(140, 40, 34),
}

local M = Enum.Material

------------------------------------------------------------------ helpers

-- A frame on the floor at (x, z) turned `yaw` degrees. Furniture faces -Z
-- of this frame (a chair's seat faces -Z, its back is at +Z).
local function at(x: number, z: number, yaw: number?, y: number?): CFrame
	return CFrame.new(x, y or 0, z) * CFrame.Angles(0, math.rad(yaw or 0), 0)
end

local function piece(f: Instance, name: string, size: Vector3, cf: CFrame, colour: Color3, material: Enum.Material?, cosmetic: boolean?): Part
	local p = part(f, name, size, cf, colour, material)
	if cosmetic then
		decor(p)
	end
	return p
end

-- Flat things on the floor (rugs, stains): cosmetic, a hair above it.
local function floorPatch(f: Instance, name: string, x1: number, x2: number, z1: number, z2: number, y: number, colour: Color3, material: Enum.Material, transparency: number?)
	local p = decor(box(f, name, x1, x2, y + 0.02, y + 0.07, z1, z2, colour, material))
	p.Transparency = transparency or 0
	return p
end

local function rug(f: Instance, x1: number, x2: number, z1: number, z2: number, y: number, colour: Color3, border: Color3)
	floorPatch(f, "RugBorder", x1, x2, z1, z2, y, border, M.Fabric)
	decor(box(f, "Rug", x1 + 0.8, x2 - 0.8, y + 0.07, y + 0.1, z1 + 0.8, z2 - 0.8, colour, M.Fabric))
end

local function chair(f: Instance, cf: CFrame, colour: Color3)
	piece(f, "ChairSeat", Vector3.new(1.6, 0.25, 1.6), cf * CFrame.new(0, 1.7, 0), colour, M.Wood)
	for _, sx in { -0.65, 0.65 } do
		for _, sz in { -0.65, 0.65 } do
			piece(f, "ChairLeg", Vector3.new(0.2, 1.6, 0.2), cf * CFrame.new(sx, 0.8, sz), colour, M.Wood)
		end
	end
	piece(f, "ChairBack", Vector3.new(1.6, 2.2, 0.2), cf * CFrame.new(0, 2.95, 0.7), colour, M.Wood)
end

local function armchair(f: Instance, cf: CFrame, colour: Color3, sheeted: boolean?)
	local c = if sheeted then C.sheet else colour
	local m = M.Fabric
	piece(f, "ArmchairBase", Vector3.new(3, 1.6, 2.8), cf * CFrame.new(0, 0.8, 0), c, m)
	piece(f, "ArmchairBack", Vector3.new(3, 2.6, 0.6), cf * CFrame.new(0, 2.6, 1.1), c, m)
	piece(f, "ArmchairArm", Vector3.new(0.5, 1, 2.8), cf * CFrame.new(-1.25, 2.1, 0), c, m)
	piece(f, "ArmchairArm", Vector3.new(0.5, 1, 2.8), cf * CFrame.new(1.25, 2.1, 0), c, m)
end

local function bookcase(f: Instance, cf: CFrame, w: number, h: number, rng: Build.Rng)
	piece(f, "BookcaseBack", Vector3.new(w, h, 0.2), cf * CFrame.new(0, h / 2, 0.6), C.walnut, M.Wood)
	piece(f, "BookcaseSide", Vector3.new(0.25, h, 1.4), cf * CFrame.new(-w / 2 + 0.125, h / 2, 0), C.walnut, M.Wood)
	piece(f, "BookcaseSide", Vector3.new(0.25, h, 1.4), cf * CFrame.new(w / 2 - 0.125, h / 2, 0), C.walnut, M.Wood)
	local shelves = math.max(2, math.floor(h / 1.6))
	for i = 0, shelves do
		local y = 0.1 + i * (h - 0.2) / shelves
		piece(f, "Shelf", Vector3.new(w - 0.5, 0.15, 1.3), cf * CFrame.new(0, y, 0), C.walnut, M.Wood)
		if i < shelves then
			local x = -w / 2 + 0.4
			while x < w / 2 - 0.6 do
				local bw = rng:number(0.18, 0.4)
				local bh = rng:number(0.8, 1.3)
				if rng:number(0, 1) > 0.12 then
					local colour = Color3.fromHSV(rng:number(0, 1), rng:number(0.2, 0.6), rng:number(0.15, 0.4))
					piece(f, "Book", Vector3.new(bw, bh, 1), cf * CFrame.new(x + bw / 2, y + 0.075 + bh / 2, 0.05), colour, M.SmoothPlastic, true)
				end
				x += bw + 0.02
			end
		end
	end
end

local function wardrobe(f: Instance, cf: CFrame)
	piece(f, "Wardrobe", Vector3.new(3.6, 7.5, 1.8), cf * CFrame.new(0, 3.75, 0), C.walnut, M.Wood)
	piece(f, "WardrobeCornice", Vector3.new(4, 0.4, 2.1), cf * CFrame.new(0, 7.7, 0), C.oakDark, M.Wood)
	piece(f, "WardrobeHandle", Vector3.new(0.1, 0.6, 0.1), cf * CFrame.new(-0.2, 3.8, -0.95), C.brass, M.Metal, true)
	piece(f, "WardrobeHandle", Vector3.new(0.1, 0.6, 0.1), cf * CFrame.new(0.2, 3.8, -0.95), C.brass, M.Metal, true)
end

local function bed(f: Instance, cf: CFrame, w: number, l: number, blanket: Color3)
	piece(f, "BedFrame", Vector3.new(w, 1.2, l), cf * CFrame.new(0, 0.6, 0), C.oakDark, M.Wood)
	piece(f, "Mattress", Vector3.new(w - 0.3, 0.6, l - 0.3), cf * CFrame.new(0, 1.5, 0), C.sheet, M.Fabric)
	piece(f, "Blanket", Vector3.new(w - 0.1, 0.25, l * 0.6), cf * CFrame.new(0, 1.85, -l * 0.18), blanket, M.Fabric, true)
	piece(f, "Pillow", Vector3.new(w - 1, 0.4, 1), cf * CFrame.new(0, 1.95, l / 2 - 0.8), C.sheet, M.Fabric, true)
	piece(f, "Headboard", Vector3.new(w, 3.2, 0.3), cf * CFrame.new(0, 1.6, l / 2 - 0.15), C.oakDark, M.Wood)
end

-- A dust-sheeted lump: something under a sheet, lumpy on top.
local function sheeted(f: Instance, cf: CFrame, size: Vector3, rng: Build.Rng)
	piece(f, "DustSheet", size, cf * CFrame.new(0, size.Y / 2, 0), C.sheet, M.Fabric)
	piece(f, "DustSheetLump", Vector3.new(size.X * rng:number(0.4, 0.7), 0.6, size.Z * rng:number(0.4, 0.7)), cf * CFrame.new(rng:number(-0.3, 0.3), size.Y + 0.25, rng:number(-0.3, 0.3)), C.sheet, M.Fabric, true)
	piece(f, "DustSheetHem", Vector3.new(size.X + 0.3, 0.3, size.Z + 0.3), cf * CFrame.new(0, 0.15, 0), C.sheetGrey, M.Fabric, true)
end

local function crateStack(f: Instance, x: number, z: number, y: number, count: number, rng: Build.Rng)
	local height = y
	for i = 1, count do
		local s = rng:number(2.4, 3.6)
		local yaw = rng:number(-12, 12)
		local c = piece(f, "Crate", Vector3.new(s, s * 0.8, s), at(x + rng:number(-0.3, 0.3), z + rng:number(-0.3, 0.3), yaw, height + s * 0.4), C.crate, M.WoodPlanks)
		if i == 1 then
			Build.label(piece(f, "CrateStencil", Vector3.new(s * 0.7, s * 0.35, 0.05), c.CFrame * CFrame.new(0, 0, -s / 2 - 0.03), C.crate, M.WoodPlanks, true), `LOT {rng:integer(120, 480)}`, Enum.NormalId.Front, C.black, Enum.Font.Arcade)
		end
		height += s * 0.8
	end
end

local function chandelier(f: Instance, x: number, ceiling: number, z: number, drop: number, radius: number)
	local y = ceiling - drop
	decor(rod(f, "ChandelierChain", Vector3.new(x, ceiling, z), Vector3.new(x, y + 0.5, z), 0.15, C.iron, M.Metal))
	piece(f, "ChandelierHub", Vector3.new(0.8, 1.4, 0.8), CFrame.new(x, y, z), C.brass, M.Metal, true)
	for i = 0, 7 do
		local a = i / 8 * math.pi * 2
		local tip = Vector3.new(x + math.cos(a) * radius, y + 0.4, z + math.sin(a) * radius)
		decor(rod(f, "ChandelierArm", Vector3.new(x, y - 0.3, z), tip, 0.12, C.brass, M.Metal))
		piece(f, "CandleStub", Vector3.new(0.2, 0.5, 0.2), CFrame.new(tip + Vector3.new(0, 0.3, 0)), C.wax, M.SmoothPlastic, true)
	end
end

-- A framed painting hung on a wall face. `axis` is the wall's axis ("X":
-- the wall runs along X, its face at z = `face`); `side` is the way the
-- face looks (+1 towards +Z / +X).
local function painting(f: Instance, axis: string, face: number, side: number, along: number, yMid: number, w: number, h: number, canvas: Color3, title: string?)
	local function plate(name: string, a1: number, a2: number, y1: number, y2: number, out1: number, out2: number, colour: Color3, material: Enum.Material): Part
		local d1, d2 = face + side * out1, face + side * out2
		if d1 > d2 then
			d1, d2 = d2, d1
		end
		if axis == "X" then
			return decor(box(f, name, a1, a2, y1, y2, d1, d2, colour, material)) :: Part
		end
		return decor(box(f, name, d1, d2, y1, y2, a1, a2, colour, material)) :: Part
	end
	plate("PaintingFrame", along - w / 2, along + w / 2, yMid - h / 2, yMid + h / 2, 0, 0.2, C.brass, M.Wood)
	plate("PaintingCanvas", along - w / 2 + 0.35, along + w / 2 - 0.35, yMid - h / 2 + 0.35, yMid + h / 2 - 0.35, 0.2, 0.25, canvas, M.Fabric)
	if title then
		local plateY = yMid - h / 2 - 0.45
		local brass = plate("PaintingPlate", along - 1.2, along + 1.2, plateY - 0.25, plateY + 0.25, 0, 0.2, C.brass, M.Metal)
		local faceId = if axis == "X" then (if side > 0 then Enum.NormalId.Back else Enum.NormalId.Front) else (if side > 0 then Enum.NormalId.Right else Enum.NormalId.Left)
		Build.label(brass, title, faceId, C.black)
	end
end

local function cobweb(f: Instance, position: Vector3, yaw: number)
	local p = piece(f, "Cobweb", Vector3.new(3, 3, 0.05), CFrame.new(position) * CFrame.Angles(0, math.rad(yaw), 0) * CFrame.Angles(0, 0, math.rad(45)), C.web, M.SmoothPlastic, true)
	p.Transparency = 0.82
end

local function candle(f: Instance, position: Vector3, lit: boolean)
	piece(f, "Candle", Vector3.new(0.25, 0.8, 0.25), CFrame.new(position + Vector3.new(0, 0.4, 0)), C.wax, M.SmoothPlastic, true)
	if lit then
		local flame = piece(f, "Flame", Vector3.new(0.12, 0.25, 0.12), CFrame.new(position + Vector3.new(0, 0.95, 0)), C.lamp, M.Neon, true)
		local light = Instance.new("PointLight")
		light.Range = 8
		light.Brightness = 0.6
		light.Color = C.lamp
		light:SetAttribute("Flicker", "bulb")
		light.Parent = flame
	end
end

local function sconce(f: Instance, axis: string, face: number, side: number, along: number, y: number, live: boolean?)
	local n = face + side * 0.3
	local x, z = if axis == "X" then along else n, if axis == "X" then n else along
	piece(f, "Sconce", Vector3.new(0.5, 0.9, 0.5), CFrame.new(x, y, z), C.brass, M.Metal, true)
	local shade = piece(f, "SconceShade", Vector3.new(0.7, 0.6, 0.7), CFrame.new(x, y + 0.75, z), if live then C.lamp else C.sheetGrey, if live then M.Neon else M.Glass, true)
	if live then
		local light = Instance.new("PointLight")
		light.Range = 14
		light.Brightness = 0.7
		light.Color = C.lamp
		light.Shadows = true
		light:SetAttribute("Flicker", "bulb")
		light.Parent = shade
	end
end

local function displayCase(f: Instance, cf: CFrame, lot: string, rng: Build.Rng)
	piece(f, "CaseBase", Vector3.new(3, 3, 4), cf * CFrame.new(0, 1.5, 0), C.walnut, M.Wood)
	local glass = piece(f, "CaseGlass", Vector3.new(3, 2.6, 4), cf * CFrame.new(0, 4.3, 0), C.glass, M.Glass)
	glass.Transparency = 0.75
	piece(f, "CaseTop", Vector3.new(3.2, 0.2, 4.2), cf * CFrame.new(0, 5.7, 0), C.walnut, M.Wood)
	piece(f, "CaseCushion", Vector3.new(2, 0.3, 2.6), cf * CFrame.new(0, 3.15, 0), C.rugRed, M.Fabric, true)
	local shapes = { Enum.PartType.Ball, Enum.PartType.Block, Enum.PartType.Cylinder }
	local relic = piece(f, "Relic", Vector3.new(0.8, 0.8, 0.8), cf * CFrame.new(0, 3.75, 0) * CFrame.Angles(0, rng:number(0, 6.28), 0), Color3.fromHSV(rng:number(0, 1), 0.2, rng:number(0.3, 0.6)), M.Metal, true)
	relic.Shape = shapes[rng:integer(1, #shapes)]
	local plate = piece(f, "CaseLabel", Vector3.new(1.8, 0.5, 0.05), cf * CFrame.new(0, 2.2, -2.03), C.paper, M.SmoothPlastic, true)
	Build.label(plate, lot, Enum.NormalId.Front, C.black)
end

local function barrel(f: Instance, x: number, y: number, z: number)
	column(f, "Barrel", x, y, z, 3, 2.2, C.oak, M.WoodPlanks)
	column(f, "BarrelHoop", x, y + 0.5, z, 0.2, 2.3, C.iron, M.Metal)
	decor(column(f, "BarrelHoop", x, y + 2.3, z, 0.2, 2.3, C.iron, M.Metal))
end

------------------------------------------------------------------ hall

local function hall(f: Instance, rng: Build.Rng)
	-- Chequered marble over the boards.
	for i = 0, 9 do
		for j = 0, 11 do
			local colour = if (i + j) % 2 == 0 then C.marbleWhite else C.marbleBlack
			floorPatch(f, "FloorTile", -60 + i * 5, -55 + i * 5, -30 + j * 5, -25 + j * 5, 0, colour, M.Marble)
		end
	end
	rug(f, -47, -25, -3, 9, 0.05, C.rugRed, C.rugGold)

	-- The cold fireplace and Cornelius over it.
	box(f, "Hearth", -40, -30, 0, 0.3, -29.5, -27, C.marbleWhite, M.Marble)
	box(f, "FireplaceJamb", -40, -38.5, 0, 7, -29.5, -28, C.marbleWhite, M.Marble)
	box(f, "FireplaceJamb", -31.5, -30, 0, 7, -29.5, -28, C.marbleWhite, M.Marble)
	box(f, "Mantel", -41, -29, 7, 7.8, -29.5, -27.6, C.marbleWhite, M.Marble)
	decor(box(f, "Firebox", -38.5, -31.5, 0.3, 5.5, -29.5, -29.3, C.black, M.Slate))
	decor(box(f, "Ash", -37.5, -32.5, 0.3, 0.6, -29.2, -28.2, C.stoneDark, M.Sand))
	painting(f, "X", -29.5, 1, -35, 13, 7, 8, C.canvas, "CORNELIUS ASHGROVE")
	for _, cx in { -39.5, -30.5 } do
		candle(f, Vector3.new(cx, 7.8, -28.4), false)
	end

	chandelier(f, -35, 24, 3, 6, 3.5)

	-- The collection's cases along the west wall.
	-- Turned -90 so their labels face into the room (+X).
	displayCase(f, at(-56.5, 8, -90), "LOT 044", rng)
	displayCase(f, at(-56.5, 13.5, -90), "LOT 061", rng)
	displayCase(f, at(-56.5, -10, -90), "LOT 090", rng)
	sheeted(f, at(-55.5, -23.5, 0), Vector3.new(5, 4, 4.5), rng) -- the piano

	-- The first crew's things.
	piece(f, "Duffel", Vector3.new(2.4, 1.1, 1.2), at(-46, -2, 20, 0.55), C.fabricGreen, M.Fabric)
	piece(f, "Duffel", Vector3.new(2.2, 1, 1.1), at(-47.5, -3.4, -15, 0.5), C.black, M.Fabric)
	decor(rod(f, "Cable", Vector3.new(-28, 0.1, -10.5), Vector3.new(-32, 0.1, -4), 0.15, C.black, M.Rubber))
	decor(rod(f, "Cable", Vector3.new(-30, 0.1, -9), Vector3.new(-40, 0.1, -7), 0.12, C.black, M.Rubber))
	chair(f, at(-40, -11, 180), C.oakDark)

	-- The way in.
	column(f, "CoatStand", -57.5, 0, -5, 6.5, 0.35, C.oakDark, M.Wood)
	piece(f, "Coat", Vector3.new(1.2, 3, 0.6), at(-57.5, -5.5, 0, 4.6), C.fabricBrown, M.Fabric, true)
	box(f, "GrandfatherClock", -14, -12, 0, 7.5, -29.4, -28, C.walnut, M.Wood)
	decor(box(f, "ClockFace", -13.7, -12.3, 5.6, 6.9, -28, -27.95, C.paper, M.SmoothPlastic))

	-- The stair's banister.
	decor(rod(f, "Banister", Vector3.new(-56.2, 4, 21.7), Vector3.new(-38.6, 15, 21.7), 0.3, C.oakDark, M.Wood))
	for i = 0, 11, 2 do
		decor(rod(f, "Baluster", Vector3.new(-56.2 + i * 1.6, 1 + i, 21.7), Vector3.new(-56.2 + i * 1.6, 4 + i * (11 / 17.6) * 1.6, 21.7), 0.18, C.oakDark, M.Wood))
	end
	crateStack(f, -14, 24, 0, 3, rng)
	crateStack(f, -24, 27, 0, 1, rng)

	-- Ceiling beams.
	for x = -55, -15, 10 do
		decor(box(f, "Beam", x - 0.6, x + 0.6, 22.8, 24, -30, 30, C.oakDark, M.Wood))
	end
	for _, corner in { Vector3.new(-58.5, 22.5, -28.5), Vector3.new(-11.5, 22.5, 28.5), Vector3.new(-58.5, 22.5, 28.5) } do
		cobweb(f, corner, 45)
	end
end

------------------------------------------------------------------ gallery

local function gallery(f: Instance, rng: Build.Rng)
	rug(f, -8, 98, -21, -17, 0, C.rugGreen, C.rugGold)
	for _, cx in { 20, 50, 80 } do
		chandelier(f, cx, 20, -19, 5, 3)
	end
	for x = -4, 104, 12 do
		decor(box(f, "Beam", x - 0.5, x + 0.5, 19, 20, -30, -8, C.oakDark, M.Wood))
	end
	-- Sconces between the portraits; only the first still works, just.
	for i = 0, 8 do
		sconce(f, "X", -8.5, -1, 8 + i * 12, 10, i == 0)
	end
	-- A second row, smaller, above the portraits.
	for i, x in { 2, 26, 50, 74, 98 } do
		painting(f, "X", -8.5, -1, x, 15.5, 4, 3.4, Color3.fromHSV(rng:number(0, 1), 0.3, 0.22), if i == 3 then "LOT 114 PROVENANCE" else nil)
	end
	armchair(f, at(30, -27.6, 180), C.fabricGreen, true)
	armchair(f, at(84, -27.6, 180), C.fabricGreen, true)
	floorPatch(f, "WaterStain", 92, 98, -29.5, -26.5, 0, C.stain, M.Slate, 0.45)
	decor(box(f, "TackCasePlate", 103, 105, 2, 2.6, -22.05, -22, C.brass, M.Metal))
	for _, corner in { Vector3.new(-8.5, 18.5, -28.5), Vector3.new(108.5, 18.5, -9.5) } do
		cobweb(f, corner, -45)
	end
end

