		piece(f, "Hook", Vector3.new(0.2, 0.2, 0.5), CFrame.new(x, 8.2, 8.75), C.iron, M.Metal, true)
		piece(f, "Coat", Vector3.new(1.2, 3.2, 0.5), CFrame.new(x, 6.4, 9), if i % 2 == 0 then C.fabricBrown else C.black, M.Fabric, true)
