	box(f, "Dresser", -9.5, -8, 0, 3.5, 15, 18.5, C.walnut, M.Wood)
	box(f, "DresserRack", -9.5, -8.8, 3.5, 8, 15, 18.5, C.walnut, M.Wood)
	for row = 0, 1 do
