	-- Housekeeper's room.
	rug(f, 64, 80, 20, 27, 0, C.rugRed, C.rugGold)
	bookcase(f, at(61.4, 23.8, -90), 5.2, 8, rng)
	chair(f, at(65, 20.4, 0), C.walnut)
