			local bottle = decor(part(f, "BottleEnd", Vector3.new(0.3, 0.6, 0.6), CFrame.new(77.9, -15 + row * 1.5, -0.8 + i * 2.1), Color3.fromRGB(30, 46, 30), M.Glass))
			bottle.Shape = Enum.PartType.Cylinder
		end
	end
	crateStack(f, 45, -2, -16, 2, rng)
