	box(f, "Trunk", 48, 51.5, -16, -13.8, -19.5, -17.5, C.oakDark, M.Wood)
	box(f, "Trunk", 53, 56, -16, -14.2, -19.5, -17.8, C.walnut, M.Wood)
	for i = 0, 3 do
