	-- Roofs.
	roofSlope(f, "X", -10, 110, -30.5, -19, eave, pitch)
	roofSlope(f, "X", -10, 110, -7.5, -19, eave, pitch)
	roofSlope(f, "X", -10, 110, 7.5, 19, eave, pitch)
	roofSlope(f, "X", -10, 110, 30.5, 19, eave, pitch)
