	box(f, "PorchRoof", -70, -60.5, 13, 14, -7.5, 7.5, C.stone, M.Cobblestone)
	box(f, "PorchPediment", -70, -60.5, 14, 15.5, -6.5, 6.5, C.stone, M.Cobblestone)
