	-- The drive: gravel, a turning circle, a dead fountain.
	local circle = decor(column(f, "TurningCircle", -92, 0, 0, 0.12, 34, Color3.fromRGB(78, 76, 72), M.Pebble))
	circle.CFrame = CFrame.new(-92, 0.06, 0) * CFrame.Angles(0, 0, math.rad(90))
	column(f, "FountainBasin", -92, 0, -27, 1.6, 10, C.limestone, M.Limestone)
	column(f, "FountainStem", -92, 1.6, -27, 4, 1.2, C.limestone, M.Limestone)
	column(f, "FountainBowl", -92, 5.6, -27, 0.6, 4, C.limestone, M.Limestone)
	decor(column(f, "FountainWater", -92, 1.3, -27, 0.2, 9, Color3.fromRGB(26, 34, 30), M.Glass))

	-- Gate piers and railings across the drive.
	for _, z in { -8, 8 } do
		box(f, "GatePier", -109.5, -106.5, 0, 7.5, z - 1.5, z + 1.5, C.stone, M.Cobblestone)
		local ball = part(f, "PierBall", Vector3.one * 2, CFrame.new(-108, 8.5, z), C.limestone, M.Limestone)
		ball.Shape = Enum.PartType.Ball
	end
	for _, side in { -1, 1 } do
		local z1, z2 = side * 9.5, side * 90
		local lo, hi = math.min(z1, z2), math.max(z1, z2)
		local fence = Build.invisible(box(f, "FenceCollider", -108.3, -107.7, 0, 7, lo, hi, C.black))
		fence.CanCollide = true
		decor(box(f, "FenceRail", -108.1, -107.9, 1, 1.2, lo, hi, C.iron, M.Metal))
		decor(box(f, "FenceRail", -108.1, -107.9, 5.6, 5.8, lo, hi, C.iron, M.Metal))
		for z = lo, hi, 2.5 do
			decor(box(f, "FencePost", -108.15, -107.85, 0, 6.4, z - 0.12, z + 0.12, C.iron, M.Metal))
		end
	end
	for _, side in { -1, 1 } do
		local z = side * 11
		box(f, "Hedge", -104, -76, 0, 4.5, z - 1, z + 1, C.hedge, M.LeafyGrass)
	end

	-- Dead trees.
	for _, p in {
		{ -200, -60 }, { -180, 40 }, { -230, -120 }, { -170, 110 }, { -260, 30 }, { -140, -80 },
		{ -150, 70 }, { -210, 160 }, { -120, -140 }, { -40, -80 }, { 10, -60 }, { 60, -95 },
		{ -30, 70 }, { 30, 62 }, { 80, 90 }, { -90, 60 }, { -78, -62 }, { 95, 48 },
	} do
		deadTree(f, p[1], p[2], rng)
	end

	-- The family plot by the cliff, and one grave dug and left open.
	for i = 0, 9 do
		local gx = 112 + (i % 5) * 3.4
		local gz = -72 + math.floor(i / 5) * 9
		local stone = part(f, "Headstone", Vector3.new(2.2, 3, 0.5), CFrame.new(gx, 1.3, gz) * CFrame.Angles(math.rad(rng:number(-9, 9)), 0, math.rad(rng:number(-6, 6))), C.limestone, M.Limestone)
		if i == 2 then
			Build.label(decor(part(f, "Epitaph", Vector3.new(1.8, 1.4, 0.05), stone.CFrame * CFrame.new(0, 0.3, 0.28), C.limestone, M.Limestone)), "ASHGROVE", Enum.NormalId.Back, C.black)
		end
	end
	box(f, "OpenGrave", 113, 117, -0.6, 0.02, -52, -50, C.black, M.Mud).CanCollide = false
	box(f, "SpoilHeap", 117.5, 120, 0, 1.4, -53, -49, C.earth, M.Mud)
	decor(rod(f, "Spade", Vector3.new(118.5, 0, -48.5), Vector3.new(119.2, 4.5, -48.2), 0.2, C.oak, M.Wood))
	local chit = part(interact:FindFirstChild("Notes") :: Instance, "Grave_Receipt", Vector3.new(1, 0.05, 1.4), CFrame.new(118.9, 3, -48.1) * CFrame.Angles(math.rad(80), 0, 0), C.paper)
	chit:SetAttribute("NoteId", "Grave_Receipt")
	for z = -78, -42, 3 do
		decor(box(f, "PlotRailing", 109, 109.2, 0, 3, z - 0.1, z + 0.1, C.iron, M.Metal))
	end
	decor(box(f, "PlotRail", 109, 109.2, 2.6, 2.8, -78, -42, C.iron, M.Metal))

	-- The cliff stair down to the boathouse: Story 2. Chained for now.
	box(f, "CliffArchPier", 123, 125, 0, 9, -89, -87, C.stone, M.Cobblestone)
	box(f, "CliffArchPier", 123, 125, 0, 9, -82, -80, C.stone, M.Cobblestone)
	box(f, "CliffArchTop", 123, 125, 9, 11, -89, -80, C.stone, M.Cobblestone)
	local gate = box(interact:FindFirstChild("Doors") :: Instance, "CliffStairGate", 123.7, 124.3, 0, 9, -87, -82, C.iron, M.Metal)
	gate:SetAttribute("DoorId", "CliffStairGate")
	gate:SetAttribute("StartsLocked", true)
	gate:SetAttribute("LockedText", "The cliff stair down to the boathouse. Chained, and the chain is wet.")

	-- Rocks at the foot of the cliff.
	for _ = 1, 26 do
		local s = rng:number(6, 16)
		part(f, "Rock", Vector3.new(s, s * rng:number(0.5, 1), s * rng:number(0.7, 1.2)), CFrame.new(rng:number(133, 160), rng:number(-126, -118), rng:number(-280, 280)) * CFrame.Angles(rng:number(0, 1), rng:number(0, 6), rng:number(0, 1)), C.stoneDark, M.Basalt)
	end

	-- A lighthouse out at sea, its beam going round.
	local lx, lz = 330, -200
	box(f, "LighthouseRock", lx - 20, lx + 20, -130, -112, lz - 20, lz + 20, C.stoneDark, M.Basalt)
	column(f, "Lighthouse", lx, -112, lz, 70, 14, C.white, M.Concrete)
	for i = 0, 2 do
		decor(column(f, "LighthouseBand", lx, -100 + i * 20, lz, 5, 14.3, C.red, M.Concrete))
	end
	column(f, "LighthouseGallery", lx, -42, lz, 1, 18, C.iron, M.Metal)
	local lamp = column(f, "LighthouseLamp", lx, -41, lz, 6, 9, C.lamp, M.Neon)
	local lampLight = Instance.new("PointLight")
	lampLight.Range = 60
	lampLight.Brightness = 2
	lampLight.Color = C.lamp
	lampLight.Parent = lamp
	column(f, "LighthouseCap", lx, -35, lz, 3, 11, C.iron, M.Metal)
	local beam = decor(part(f, "LighthouseBeam", Vector3.new(4, 4, 360), CFrame.new(lx, -38, lz) * CFrame.new(0, 0, -180), C.lamp, M.Neon))
	beam.Transparency = 0.86
	beam:SetAttribute("Spin", true)
	beam:SetAttribute("SpinCentre", Vector3.new(lx, -38, lz))
end

------------------------------------------------------------------ entry

function Dressing.dress(root: Model)
	local geo = root:FindFirstChild("Geometry") :: Instance
	local interact = root:FindFirstChild("Interact") :: Instance
	local rng = Build.random(1907)
	hall(Build.folder(geo, "HallDressing"), rng)
	gallery(Build.folder(geo, "GalleryDressing"), rng)
	servants(Build.folder(geo, "ServantsDressing"), rng)
	vault(Build.folder(geo, "VaultDressing"), rng)
	exterior(Build.folder(geo, "Exterior"), interact, rng)
end

return Dressing
]=] },
	{ service = {"ServerScriptService"}, path = {"Ashgrove", "Entities"}, class = "Folder", source = nil },
	{ service = {"ServerScriptService"}, path = {"Ashgrove", "Entities", "Dullahan"}, class = "ModuleScript", source = [=[
--[[
	The Dullahan (portrait gallery). Killable. Lot 114, the spine whip.

	RULE: it sees only what its carried head is facing.

	- Idle: walks the gallery, stopping to hold the head up to portraits
	  and windows. Stay out of the head's view and you can pass behind him.
	- The kill window closes at whip reach (about 12 studs), not contact.
	- Weak point: the head. Hit it and he drops it and gropes blind for
	  Config.blindTime seconds; body shots then kill him. Body shots while
	  he holds the head only stagger him.
	- Gold raised where the head can see it drives him back. No kill.
	- Death: the body falls apart, the head keeps glowing where it rolled
	  for a while (a light source), and the Banshee may come to mourn.
]]

local Debris = game:GetService("Debris")
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local TweenService = game:GetService("TweenService")

local Shared = ReplicatedStorage:WaitForChild("Ashgrove")
local Audio = require(Shared:WaitForChild("Audio"))
local Config = require(Shared:WaitForChild("Config"))

local Ashgrove = script.Parent.Parent
local Crew = require(Ashgrove.Crew)
local Map = require(Ashgrove.Map)
local Noise = require(Ashgrove.Noise)
local Say = require(Ashgrove.Say)
local Rigs = require(script.Parent.Rigs)

local cfg = Config.entities.Dullahan

local Dullahan = {}

local function flat(v: Vector3): Vector3
	local f = Vector3.new(v.X, 0, v.Z)
	return if f.Magnitude > 1e-4 then f.Unit else Vector3.new(0, 0, -1)
end

local function hasHead(e): boolean
	local d = e.data
	return not d.blind and d.head ~= nil and d.headJoint ~= nil and d.headJoint.Parent ~= nil
end

-- Sets the head's turn on its joint (C0 if the head is the joint's Part1,
-- otherwise C1), from the pose it had when built.
local function poseHead(d)
	local turn = CFrame.Angles(0, d.headYaw or 0, 0)
	if d.headJoint.Part1 == d.head then
		d.headJoint.C0 = d.headBase * turn
	else
		d.headJoint.C1 = d.headBase * turn:Inverse()
	end
end

local function headLook(e): Vector3
	return flat(e.data.head.CFrame.LookVector)
end

-- Turns the carried head towards a world direction, at `rate` radians/s.
local function turnHeadTowards(e, direction: Vector3, dt: number, rate: number)
	if not hasHead(e) then
		return
	end
	local rel = e.root.CFrame:VectorToObjectSpace(flat(direction))
	local target = math.clamp(math.atan2(-rel.X, -rel.Z), math.rad(-150), math.rad(150))
	local current = e.data.headYaw or 0
	local step = math.clamp(target - current, -rate * dt, rate * dt)
	e.data.headYaw = current + step
	poseHead(e.data)
end

local function headSees(e, player: Player, range: number): boolean
	if not hasHead(e) then
		return false
	end
	local head = Crew.head(player)
	if not head then
		return false
	end
	local from = e.data.head.Position
	local offset = head.Position - from
	if offset.Magnitude > range then
		return false
	end
	local inCone = headLook(e):Dot(flat(offset)) >= math.cos(math.rad(cfg.fieldOfView / 2))
	return inCone and e:canSee(from, player, range)
end

local function findTarget(e): Player?
	local best, bestDistance = nil, math.huge
	for _, player in e:targets() do
		local d = e:distanceTo(player)
		if d < bestDistance and (d <= cfg.touchRange or headSees(e, player, cfg.sightRange)) then
			best, bestDistance = player, d
		end
	end
	return best
end

local function startHunt(e, player: Player)
	local d = e.data
	local wasHunting = e.state == "Hunt" or e.state == "Windup" or e.state == "Recover"
	d.target = player
	d.lastSeen = os.clock()
	local root = Crew.root(player)
	d.lastSeenPos = if root then root.Position else e.root.Position
	if not wasHunting then
		Say.to(player, "[The head turns towards you]", 3, "sound")
		Audio.play("dullahanBreath", e.root, 0.8)
	end
	e:setState("Hunt")
end

local function alert(e, position: Vector3)
	e.data.alertPos = position
	e:setState("Alert")
end

local function dropHead(e)
	local d = e.data
	if not hasHead(e) or not d.canDropHead then
		return
	end
	d.headJoint:Destroy()
	d.headJoint = nil
	d.blind = true
	d.bodyHits = 0
	local head: BasePart = d.head
	head.Massless = false
	head.CanCollide = true
	head.AssemblyLinearVelocity = flat(e.root.CFrame.LookVector) * 6 + Vector3.new(0, 8, 0)
	pcall(function()
		head:SetNetworkOwner(nil)
	end)
	Audio.play("headDrop", head, 0.8)
	Noise.emit(head.Position, 25, "impact")
	e.animOverride = "blind"
	e:setState("Blind")
end

local function returnHead(e)
	local d = e.data
	local head: BasePart = d.head
	if not head or not head.Parent or not e.root then
		return
	end
	head.CanCollide = false
	head.Massless = true
	head.AssemblyLinearVelocity = Vector3.zero
	d.headYaw = 0
	local joint = d.headTemplate:Clone()
	joint.Parent = head
	d.headJoint = joint
	poseHead(d)
	d.blind = false
	e.animOverride = nil
	Say.near(e.root.Position, 60, "[He finds his head]", 3, "sound")
end

local function repel(e, from: Vector3)
	e.data.repelFrom = from
	e:setState("Repelled")
	Say.near(e.root.Position, 50, "[He recoils from the gold]", 3, "sound")
end

------------------------------------------------------------------ behaviour

function Dullahan.build(e)
	local model, root, humanoid, parts = Rigs.dullahan()
	local joint = parts.headJoint
	e.data.head = parts.head
	e.data.headJoint = joint
	-- Kept to put the head back after it's been shot out of his hands.
	e.data.headTemplate = joint:Clone()
	e.data.headBase = if joint.Part1 == parts.head then joint.C0 else joint.C1
	e.data.canDropHead = parts.head ~= root
	e.data.headYaw = 0
	e.data.route = Map.markers("Dullahan_Route_")
	e.data.routeIndex = 1
	e.data.routeDir = 1
	e.data.pauseUntil = 0
	e.data.nextTrace = os.clock() + 15
	return model, root, humanoid
end

function Dullahan.step(e, dt: number)
	local d = e.data
	local now = os.clock()
	local root: BasePart = e.root

	-- Traces before contact: a whip-crack that carries out of the gallery.
	if now >= d.nextTrace and (e.state == "Idle" or e.state == "Alert") then
		d.nextTrace = now + 20 + math.random() * 20
		Audio.play("dullahanWhip", root, 0.5, 200)
		Say.near(root.Position, 160, "[A whip-crack, somewhere down the gallery]", 3, "sound")
	end

	-- Gold he can see drives him back.
	if hasHead(e) and e.state ~= "Repelled" then
		for _, player in Crew.activePlayers() do
			if Crew.isWardRaised(player) and headSees(e, player, Config.ward.range) then
				local r = Crew.root(player)
				if r then
					repel(e, r.Position)
				end
				break
			end
		end
	end

	local state = e.state
	if state == "Idle" then
		local seen = findTarget(e)
		if seen then
			startHunt(e, seen)
			return
		end
		local route = d.route
		if #route == 0 then
			e:stop()
			return
		end
		local stop: BasePart = route[d.routeIndex]
		local offset = stop.Position - root.Position
		if Vector3.new(offset.X, 0, offset.Z).Magnitude < 3 then
			e:stop()
			if d.pauseUntil == 0 then
				d.pauseUntil = now + cfg.idlePauseMin + math.random() * (cfg.idlePauseMax - cfg.idlePauseMin)
			end
			local look = stop:GetAttribute("Look")
			if typeof(look) == "Vector3" then
				turnHeadTowards(e, look - root.Position, dt, 1.5)
			end
			if now >= d.pauseUntil then
				d.pauseUntil = 0
				local nextIndex = d.routeIndex + d.routeDir
				if nextIndex < 1 or nextIndex > #route then
					d.routeDir = -d.routeDir
					nextIndex = d.routeIndex + d.routeDir
				end
				d.routeIndex = math.clamp(nextIndex, 1, #route)
			end
		else
			e:moveTo(stop.Position, cfg.walkSpeed)
			-- The head sweeps slowly while he walks.
			local sweep = math.sin(now * 0.6) * 0.9
			turnHeadTowards(e, root.CFrame:VectorToWorldSpace(CFrame.Angles(0, sweep, 0).LookVector), dt, 1.2)
		end
	elseif state == "Alert" then
		local seen = findTarget(e)
		if seen then
			startHunt(e, seen)
			return
		end
		local goal: Vector3 = d.alertPos or root.Position
		turnHeadTowards(e, goal - root.Position, dt, 2.5)
		if (Vector3.new(goal.X - root.Position.X, 0, goal.Z - root.Position.Z)).Magnitude > 4 then
			e:moveTo(goal, cfg.walkSpeed)
		else
			e:stop()
		end
		if e:inState() > cfg.searchTime then
			e:setState("Idle")
		end
	elseif state == "Hunt" then
		local target: Player? = d.target
		if not e:canTarget(target) then
			alert(e, d.lastSeenPos or root.Position)
			return
		end
		local targetRoot = Crew.root(target :: Player) :: BasePart
		if headSees(e, target :: Player, cfg.sightRange) or e:distanceTo(target :: Player) <= cfg.touchRange then
			d.lastSeen = now
			d.lastSeenPos = targetRoot.Position
		elseif now - (d.lastSeen or 0) > cfg.loseTargetAfter then
			alert(e, d.lastSeenPos)
			return
		end
		turnHeadTowards(e, targetRoot.Position - root.Position, dt, 5)
		local distance = e:distanceTo(target :: Player)
		if distance <= cfg.whipRange and e:canSee(root.Position, target :: Player, cfg.whipRange + 2) then
			e:stop()
			e:face(targetRoot.Position)
			Say.to(target :: Player, "[The whip draws back]", 2, "sound")
			e:setState("Windup")
		else
			e:moveTo(targetRoot.Position, cfg.huntSpeed)
		end
	elseif state == "Windup" then
		local target: Player? = d.target
		if target and Crew.root(target) then
			e:face((Crew.root(target) :: BasePart).Position)
		end
		if e:inState() >= cfg.windupTime then
			e:action("attack")
			Audio.play("dullahanWhip", root, 1, 200)
			Say.near(root.Position, 80, "[CRACK]", 2, "sound")
			if target and e:canTarget(target) and e:distanceTo(target) <= cfg.whipRange + 1.5 and e:canSee(root.Position, target, cfg.whipRange + 3) then
				Crew.hit(target, 1)
			end
			e:setState("Recover")
		end
	elseif state == "Recover" then
		e:stop()
		if e:inState() >= cfg.recoverTime then
			if e:canTarget(d.target) then
				e:setState("Hunt")
			else
				alert(e, d.lastSeenPos or root.Position)
			end
		end
	elseif state == "Stagger" then
		e:stop()
		if e:inState() >= cfg.staggerTime then
			if e:canTarget(d.target) then
				startHunt(e, d.target)
			else
				alert(e, d.lastSeenPos or root.Position)
			end
		end
	elseif state == "Blind" then
		-- Groping towards the last thing he heard.
		local goal: Vector3? = d.gropeTo
		if goal and (Vector3.new(goal.X - root.Position.X, 0, goal.Z - root.Position.Z)).Magnitude > 3 then
			e:moveTo(goal, 5)
		else
			e:stop()
		end
		if e:inState() >= cfg.blindTime then
			returnHead(e)
			local seen = findTarget(e)
			if seen then
				startHunt(e, seen)
			else
				alert(e, d.lastSeenPos or root.Position)
			end
		end
	elseif state == "Repelled" then
		local from: Vector3 = d.repelFrom or root.Position
		turnHeadTowards(e, from - root.Position, dt, 4)
		local away = flat(root.Position - from)
		e:moveTo(root.Position + away * 10, cfg.huntSpeed)
		if e:inState() >= cfg.repelTime then
			if e:canTarget(d.target) then
				e:setState("Hunt")
			else
				e:setState("Idle")
			end
		end
	end
end

function Dullahan.onShot(e, part: BasePart, shooter: Player, _position: Vector3)
	local d = e.data
	local hitbox = part:GetAttribute("Hitbox")
	if hitbox == "Head" and hasHead(e) then
		d.target = shooter
		d.lastSeen = os.clock()
		dropHead(e)
		Say.to(shooter, "Hit the head. He's blind. Now.", 3, "hint")
		Say.near(e.root.Position, 80, "[The head hits the floor and rolls]", 3, "sound")
		return
	end
	if d.blind then
		d.bodyHits = (d.bodyHits or 0) + 1
		if d.bodyHits >= cfg.bodyHitsToKillWhileBlind then
			e:banish(shooter)
		else
			Say.near(e.root.Position, 60, "[He staggers]", 2, "sound")
		end
		return
	end
	if not d.taughtBody then
		d.taughtBody = true
		Say.to(shooter, "Body shots don't stop him.", 3, "hint")
	end
	d.target = shooter
	d.lastSeen = os.clock()
	local r = Crew.root(shooter)
	d.lastSeenPos = if r then r.Position else e.root.Position
	e:setState("Stagger")
end

function Dullahan.onNoise(e, noise, sameWing: boolean)
	local d = e.data
	if e.state == "Blind" then
		if sameWing then
			d.gropeTo = noise.position
		end
		return
	end
	if e.state == "Idle" or e.state == "Alert" then
		if sameWing then
			alert(e, noise.position)
		end
	end
end

function Dullahan.onAgitate(e, position: Vector3)
	if e.state == "Idle" then
		alert(e, position)
	end
end

function Dullahan.onBanish(e, model: Model, _killer: Player?)
	local d = e.data
	local head: BasePart? = d.head
	local position = model:GetPivot().Position
	-- The head stays, still glowing, where it rolled.
	if head and d.canDropHead then
		if d.headJoint then
			d.headJoint:Destroy()
		end
		head.Massless = false
		head.CanCollide = true
		head.CanQuery = false
		head:SetAttribute("LightRadius", cfg.headGlowRadius)
		head.Parent = Map.interact("Glows")
		pcall(function()
			head:SetNetworkOwner(nil)
		end)
		Debris:AddItem(head, cfg.headGlowTime)
	end
	-- The body comes apart.
	local root = model:FindFirstChild("HumanoidRootPart") :: BasePart?
	if root then
		root.Anchored = true
		root.CanCollide = false
	end
	for _, p in model:GetDescendants() do
		if p:IsA("WeldConstraint") or p:IsA("JointInstance") then
			p:Destroy()
		elseif p:IsA("BasePart") and p ~= root then
			p.CanCollide = true
			p.CanQuery = false
		end
	end
	task.delay(5, function()
		for _, p in model:GetDescendants() do
			if p:IsA("BasePart") then
				TweenService:Create(p, TweenInfo.new(3), { Transparency = 1 }):Play()
			end
		end
		task.delay(3, function()
			model:Destroy()
		end)
	end)
	for _, player in Players:GetPlayers() do
		local r = Crew.root(player)
		if r and (r.Position - position).Magnitude < 120 then
			Say.to(player, "[He comes apart. The head keeps glowing.]", 4, "sound")
		end
	end
end

return Dullahan
]=] },
	{ service = {"ServerScriptService"}, path = {"Ashgrove", "Entities", "Entity"}, class = "ModuleScript", source = [=[
--[[
	Entity: what every killable entity shares. A behaviour module (Dullahan,
	Lampshy) supplies the rule; this supplies the body, the binding and
	the movement.

	The binding (direction doc, section 6):
	  - killing a manifestation BANISHES it back into its object. It
	    re-forms at its spawn after Config.entities.reformMin..Max seconds
	  - securing the object (Retrieval) removes it for the rest of the story
	  - every banish fires Registry.died, which the Banshee counts as a death

	status: "dormant" (not in the story yet) | "active" | "banished" | "secured"

	Entities never leave their wing, and never target players who are in a
	sanctuary or outside the wing.

	A behaviour module provides:
	  build(e) -> (Model, root: BasePart, Humanoid)   e.data is fresh
	  step(e, dt)
	  onShot(e, part, shooter, position)
	  onNoise(e, noise)?   onAgitate(e, position)?   onBanish(e, model, killer)?
]]

local Players = game:GetService("Players")
local PathfindingService = game:GetService("PathfindingService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local TweenService = game:GetService("TweenService")

local Config = require(ReplicatedStorage:WaitForChild("Ashgrove"):WaitForChild("Config"))

local Ashgrove = script.Parent.Parent
local Crew = require(Ashgrove.Crew)
local Map = require(Ashgrove.Map)
local Models = require(Ashgrove.Models)
local Noise = require(Ashgrove.Noise)
local Shots = require(Ashgrove.Shots)
local Registry = require(script.Parent.Registry)

local Entity = {}
Entity.__index = Entity

local entityFolder: Folder? = nil
local function folder(): Folder
	if not entityFolder or not entityFolder.Parent then
		local f = Instance.new("Folder")
		f.Name = "Entities"
		f.Parent = Map.root()
		entityFolder = f
	end
	return entityFolder :: Folder
end

function Entity.new(id: string, cfg: { [string]: any }, behaviour: { [string]: any })
	local self = setmetatable({
		id = id,
		cfg = cfg,
		wing = cfg.wing,
		behaviour = behaviour,
		status = "dormant",
		model = nil :: Model?,
		root = nil :: BasePart?,
		humanoid = nil :: Humanoid?,
		state = "Idle",
		stateAt = 0,
		data = {} :: { [string]: any },
		reformAt = 0,
		waypoints = nil :: { PathWaypoint }?,
		waypointIndex = 0,
		pathGoal = Vector3.zero,
		pathAt = 0,
		pathBusy = false,
		anim = nil :: Models.Animations?,
		animOverride = nil :: string?,
	}, Entity)
	Registry.add(self)
	return self
end

function Entity:setState(name: string)
	if self.state ~= name then
		self.state = name
		self.stateAt = os.clock()
	end
end

function Entity:inState(): number
	return os.clock() - self.stateAt
end

function Entity:position(): Vector3?
	return if self.root then self.root.Position else nil
end

-- Brings a dormant entity into the story.
function Entity:activate()
	if self.status == "dormant" then
		self:spawn()
	end
end

function Entity:spawn()
	local marker = Map.marker(self.id .. "_Spawn")
	self.data = {}
	self.waypoints = nil
	local model, root, humanoid = self.behaviour.build(self)
	model:SetAttribute("EntityId", self.id)
	model:PivotTo(marker.CFrame)
	-- Stand it on the floor whatever its size (your model may be taller
	-- or shorter than the greybox).
	local params = RaycastParams.new()
	params.FilterType = Enum.RaycastFilterType.Exclude
	params.FilterDescendantsInstances = { model }
	local floor = workspace:Raycast(marker.Position + Vector3.new(0, 2, 0), Vector3.new(0, -30, 0), params)
	if floor then
		local box, size = model:GetBoundingBox()
		local bottom = box.Position.Y - size.Y / 2
		model:PivotTo(model:GetPivot() + Vector3.new(0, floor.Position.Y + 0.05 - bottom, 0))
	end
	model.Parent = folder()
	root:SetNetworkOwner(nil)
	self.model, self.root, self.humanoid = model, root, humanoid
	self.anim = Models.animations(model, self.id)
	self.animOverride = nil

	-- Your gun's damage is the confirmed hit (see Shots). Health is topped
	-- straight back up: Ashgrove's monsters die by their rules, not by HP.
	local lastHealth = humanoid.Health
	humanoid.HealthChanged:Connect(function(health)
		if health < lastHealth - 0.01 and self.humanoid == humanoid then
			humanoid.Health = humanoid.MaxHealth
			lastHealth = humanoid.MaxHealth
			Shots.onDamaged(self)
		else
			lastHealth = health
		end
	end)
	self.status = "active"
	self.state = ""
	self:setState("Idle")
	if self.behaviour.onSpawn then
		self.behaviour.onSpawn(self)
	end
	Registry.formed:Fire(self)
end

local function fadeOut(model: Model, seconds: number)
	for _, p in model:GetDescendants() do
		if p:IsA("BasePart") then
			p.CanCollide = false
			p.CanQuery = false
			TweenService:Create(p, TweenInfo.new(seconds), { Transparency = 1 }):Play()
		end
	end
	task.delay(seconds, function()
		model:Destroy()
	end)
end

-- Killed: back into its object for a while.
function Entity:banish(killer: Player?)
	if self.status ~= "active" or not self.root or not self.model then
		return
	end
	local position = self.root.Position
	local model = self.model :: Model
	model:SetAttribute("EntityId", nil)
	self.status = "banished"
	self.model, self.root, self.humanoid = nil, nil, nil
	self.waypoints = nil
	local e = Config.entities
	self.reformAt = os.clock() + e.reformMin + math.random() * (e.reformMax - e.reformMin)
	if self.behaviour.onBanish then
		self.behaviour.onBanish(self, model, killer)
	else
		fadeOut(model, 1)
	end
	Registry.died:Fire(self, position, killer)
end

-- Its object is in a warded crate: gone for the rest of the story.
function Entity:secure()
	if self.model then
		local model = self.model :: Model
		model:SetAttribute("EntityId", nil)
		fadeOut(model, 1.5)
	end
	self.model, self.root, self.humanoid = nil, nil, nil
	self.status = "secured"
end

-- Checkpoint reset: back to its spawn, unaware.
function Entity:reset()
	if self.status == "active" then
		if self.model then
			self.model:Destroy()
		end
		self.model, self.root, self.humanoid = nil, nil, nil
		self:spawn()
	end
end

-- Despawn without killing (story end).
function Entity:retire()
	if self.model then
		fadeOut(self.model :: Model, 1.5)
	end
	self.model, self.root, self.humanoid = nil, nil, nil
	self.status = "secured"
end

------------------------------------------------------------------ senses

function Entity:ignoreList(): { Instance }
	local list: { Instance } = { Map.interact("Glows") }
	if self.model then
		table.insert(list, self.model)
	end
	for _, player in Players:GetPlayers() do
		if player.Character then
			table.insert(list, player.Character)
		end
	end
	return list
end

-- Can a point see this player's head, with nothing in between?
function Entity:canSee(from: Vector3, player: Player, maxRange: number): boolean
	local head = Crew.head(player)
	local character = player.Character
	if not head or not character then
		return false
	end
	local offset = head.Position - from
	if offset.Magnitude > maxRange then
		return false
	end
	local params = RaycastParams.new()
	params.FilterType = Enum.RaycastFilterType.Exclude
	local ignore: { Instance } = { Map.interact("Glows") }
	if self.model then
		table.insert(ignore, self.model)
	end
	params.FilterDescendantsInstances = ignore
	local hit = workspace:Raycast(from, offset, params)
	return hit == nil or hit.Instance:IsDescendantOf(character)
end

-- Players it may go after: targetable and inside its wing.
function Entity:targets(): { Player }
	local out = {}
	for _, player in Crew.playersInWing(self.wing) do
		if Crew.isTargetable(player) then
			table.insert(out, player)
		end
	end
	return out
end

function Entity:distanceTo(player: Player): number
	local root = Crew.root(player)
	if not root or not self.root then
		return math.huge
	end
	return (root.Position - self.root.Position).Magnitude
end

function Entity:nearestTarget(): Player?
	local best, bestDistance = nil, math.huge
	for _, player in self:targets() do
		local d = self:distanceTo(player)
		if d < bestDistance then
			best, bestDistance = player, d
		end
	end
	return best
end

function Entity:canTarget(player: Player?): boolean
	if not player or not Crew.isTargetable(player) then
		return false
	end
	local root = Crew.root(player)
	return root ~= nil and Map.wingAt(root.Position) == self.wing
end

------------------------------------------------------------------ movement

local function clearTo(self, goal: Vector3): boolean
	local from = self.root.Position
	local to = Vector3.new(goal.X, from.Y, goal.Z)
	local params = RaycastParams.new()
	params.FilterType = Enum.RaycastFilterType.Exclude
	params.FilterDescendantsInstances = self:ignoreList()
	return workspace:Raycast(from, to - from, params) == nil
end

function Entity:moveTo(goal: Vector3, speed: number)
	local humanoid, root = self.humanoid, self.root
	if not humanoid or not root then
		return
	end
	humanoid.WalkSpeed = speed
	if Map.wingAt(goal) ~= self.wing then
		self:stop()
		return
	end
	if clearTo(self, goal) then
		self.waypoints = nil
		humanoid:MoveTo(goal)
		return
	end
	local now = os.clock()
	if not self.pathBusy and (self.waypoints == nil or now - self.pathAt > 1 or (self.pathGoal - goal).Magnitude > 4) then
		self.pathBusy = true
		self.pathAt = now
		self.pathGoal = goal
		local from = root.Position
		task.spawn(function()
			local path = PathfindingService:CreatePath({
				AgentRadius = self.cfg.agentRadius or 2,
				AgentHeight = self.cfg.agentHeight or 6,
				AgentCanJump = false,
			})
			local ok = pcall(function()
				path:ComputeAsync(from, goal)
			end)
			if ok and path.Status == Enum.PathStatus.Success then
				self.waypoints = path:GetWaypoints()
				self.waypointIndex = 2
			else
				self.waypoints = nil
			end
			self.pathBusy = false
		end)
	end
	local waypoints = self.waypoints
	if waypoints and waypoints[self.waypointIndex] then
		local wp = waypoints[self.waypointIndex].Position
		local flat = Vector3.new(wp.X - root.Position.X, 0, wp.Z - root.Position.Z)
		if flat.Magnitude < 2.5 and self.waypointIndex < #waypoints then
			self.waypointIndex += 1
			wp = waypoints[self.waypointIndex].Position
		end
		humanoid:MoveTo(wp)
	end
end

function Entity:stop()
	if self.humanoid and self.root then
		self.humanoid.WalkSpeed = 0
		self.humanoid:MoveTo(self.root.Position)
	end
end

-- Turn the body to face a point (only while stopped).
function Entity:face(point: Vector3)
	local root = self.root
	if root then
		local flat = Vector3.new(point.X, root.Position.Y, point.Z)
		if (flat - root.Position).Magnitude > 0.1 then
			root.CFrame = CFrame.lookAt(root.Position, flat)
		end
	end
end

-- A one-off animation (Config.models[id].animations), e.g. "attack".
function Entity:action(name: string)
	if self.anim then
		self.anim.action(name)
	end
end

function Entity:shot(part: BasePart, shooter: Player, position: Vector3)
	if self.status == "active" then
		self.behaviour.onShot(self, part, shooter, position)
	end
end

function Entity:agitate(position: Vector3)
	if self.status == "active" and self.behaviour.onAgitate then
		self.behaviour.onAgitate(self, position)
	end
end

------------------------------------------------------------------ loop

local function playerNear(position: Vector3, radius: number): boolean
	for _, player in Players:GetPlayers() do
		local root = Crew.root(player)
		if root and (root.Position - position).Magnitude < radius then
			return true
		end
	end
	return false
end

function Entity.startLoop()
	Noise.emitted:Connect(function(noise: Noise.Noise)
		for _, e in Registry.all() do
			if e.status == "active" and e.root and e.behaviour.onNoise then
				local hearing = noise.radius * (e.cfg.hearingMultiplier or 1)
				local sameWing = Map.wingAt(noise.position) == e.wing
				if (sameWing or noise.kind == "gunshot") and (noise.position - e.root.Position).Magnitude <= hearing then
					e.behaviour.onNoise(e, noise, sameWing)
				end
			end
		end
	end)

	task.spawn(function()
		local last = os.clock()
		while true do
			task.wait(Config.entities.stepInterval)
			local now = os.clock()
			local dt = now - last
			last = now
			for _, e in Registry.all() do
				if e.status == "active" then
					if not e.model or not e.model.Parent or not e.root then
						-- Lost its body (destroyed by something else): re-form later.
						e.status = "banished"
						e.model, e.root, e.humanoid = nil, nil, nil
						e.reformAt = now + Config.entities.reformMin
					else
						if Map.wingAt(e.root.Position) ~= e.wing then
							-- Strayed out of its wing: walk home.
							e.humanoid:MoveTo(Map.marker(e.id .. "_Spawn").Position)
						end
						local ok, err = pcall(e.behaviour.step, e, dt)
						if not ok then
							warn(`[Ashgrove] {e.id} step failed: {err}`)
						end
						if e.anim and e.root then
							local v = e.root.AssemblyLinearVelocity
							local speed = Vector3.new(v.X, 0, v.Z).Magnitude
							e.anim.loop(e.animOverride or (if speed > 10 then "run" elseif speed > 0.5 then "walk" else "idle"))
						end
					end
				elseif e.status == "banished" and now >= e.reformAt then
					local spawnAt = Map.marker(e.id .. "_Spawn").Position
					if playerNear(spawnAt, Config.entities.reformClearRadius) then
						e.reformAt = now + 10
					else
						e:spawn()
					end
				end
			end
		end
	end)
end

return Entity
]=] },
	{ service = {"ServerScriptService"}, path = {"Ashgrove", "Entities", "Lampshy"}, class = "ModuleScript", source = [=[
--[[
	The Lamp-shy (servants' wing). Killable. Lot 203, the hollow lantern.

	PLACEHOLDER for open decision #1 in docs/ASHGROVE_DIRECTION.md: Story 1
	needs a second, cheaper killable entity with a different approach from
	the Dullahan. Swap the rig and the name when the team picks one; keep
	a one-sentence rule.

	RULE: it only moves while it's out of the light.

	- Hunts by sound: walking carries a short way, sprinting a long way,
	  crouching not at all.
	- In any light (a torch beam, a lamp, a glow, a lightning flash) it
	  freezes completely. Reloading turns your torch off, so a lone player
	  can't light it and reload at the same time. Two players can.
	- Kill: one shot while it's lit. In the dark the shot finds nothing.
	- Death: it collapses into a pale glowing shape, a light source that
	  lasts a few minutes.
]]

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local TweenService = game:GetService("TweenService")

local Shared = ReplicatedStorage:WaitForChild("Ashgrove")
local Audio = require(Shared:WaitForChild("Audio"))
local Config = require(Shared:WaitForChild("Config"))

local Ashgrove = script.Parent.Parent
local Crew = require(Ashgrove.Crew)
local Light = require(Ashgrove.Light)
local Map = require(Ashgrove.Map)
local Say = require(Ashgrove.Say)
local Rigs = require(script.Parent.Rigs)

local cfg = Config.entities.Lampshy

local Lampshy = {}

local function isLit(e): boolean
	return Light.isLit(e.root.Position + Vector3.new(0, 0.5, 0), { e.model })
end

local function hunt(e, player: Player)
	e.data.target = player
	e.data.lastHeard = os.clock()
	if e.state ~= "Hunt" then
		Audio.play("lampshyChitter", e.root, 0.8)
		e:setState("Hunt")
	end
end

-- The route marker furthest from a point, that isn't lit.
local function darkestRetreat(e, from: Vector3): Vector3
	local best, bestDistance = e.root.Position, -1
	for _, m in e.data.route do
		local d = (m.Position - from).Magnitude
		if d > bestDistance and not Light.isLit(m.Position, { e.model }) then
			best, bestDistance = m.Position, d
		end
	end
	return best
end

function Lampshy.build(e)
	local model, root, humanoid = Rigs.lampshy()
	e.data.route = Map.markers("Lampshy_Route_")
	e.data.nextTrace = os.clock() + 10
	e.data.nextWanderRoll = os.clock() + 10
	return model, root, humanoid
end

function Lampshy.onSpawn(e)
	e:setState("Feed")
end

function Lampshy.step(e, _dt: number)
	local d = e.data
	local now = os.clock()
	local root: BasePart = e.root

	-- A light on it tells it exactly where the light came from.
	local beamPlayer = Light.beamOn(root.Position + Vector3.new(0, 0.5, 0), nil, { e.model })
	if beamPlayer and e:canTarget(beamPlayer) and e.state ~= "Hunt" then
		hunt(e, beamPlayer)
	end

	if isLit(e) then
		if not d.frozen then
			d.frozen = true
			if e.state == "Hunt" or e.state == "Retreat" then
				Say.near(root.Position, 40, "[It stops dead in the light]", 2, "sound")
			end
		end
		e:stop()
		return
	end
	d.frozen = false

	-- Anyone close enough to touch, it knows about.
	for _, player in e:targets() do
		if e:distanceTo(player) <= cfg.touchRange then
			hunt(e, player)
			break
		end
	end

	local state = e.state
	if state == "Feed" or state == "Idle" then
		e:stop()
		if now >= d.nextTrace then
			d.nextTrace = now + 18 + math.random() * 14
			Audio.play("lampshyChitter", root, 0.4)
			Say.near(root.Position, 35, "[Wet chewing, somewhere in the dark]", 3, "sound")
		end
		if now >= d.nextWanderRoll then
			d.nextWanderRoll = now + 10
			if math.random() < cfg.idleWanderChance and #d.route > 0 then
				d.wanderTo = d.route[math.random(1, #d.route)].Position
				e:setState("Wander")
			end
		end
	elseif state == "Wander" then
		local goal: Vector3 = d.wanderTo or root.Position
		if (Vector3.new(goal.X - root.Position.X, 0, goal.Z - root.Position.Z)).Magnitude < 3 or e:inState() > 25 then
			e:setState("Feed")
		else
			e:moveTo(goal, cfg.wanderSpeed)
		end
	elseif state == "Hunt" then
		local target: Player? = d.target
		if not e:canTarget(target) or now - (d.lastHeard or 0) > cfg.loseTargetAfter then
			d.target = nil
			d.wanderTo = Map.marker("Lampshy_Spawn").Position
			e:setState("Wander")
			return
		end
		local targetRoot = Crew.root(target :: Player) :: BasePart
		if e:distanceTo(target :: Player) <= cfg.lungeRange then
			e:action("attack")
			Audio.play("lampshyLunge", root, 1)
			Say.near(root.Position, 40, "[It lunges]", 2, "sound")
			Crew.hit(target :: Player, 1)
			d.retreatTo = darkestRetreat(e, targetRoot.Position)
			e:setState("Retreat")
		else
			e:moveTo(targetRoot.Position, cfg.speed)
		end
	elseif state == "Retreat" then
		e:moveTo(d.retreatTo or root.Position, cfg.speed)
		if e:inState() >= cfg.retreatTime then
			if e:canTarget(d.target) then
				d.lastHeard = now
				e:setState("Hunt")
			else
				e:setState("Feed")
			end
		end
	end
end

function Lampshy.onShot(e, _part: BasePart, shooter: Player, _position: Vector3)
	if isLit(e) then
		e:banish(shooter)
	else
		Say.to(shooter, "Nothing. It isn't there in the dark. Get a light on it.", 3, "hint")
		if e:canTarget(shooter) then
			hunt(e, shooter)
		end
	end
end

function Lampshy.onNoise(e, noise, sameWing: boolean)
	if not sameWing then
		return
	end
	local source: Player? = noise.source
	if source and e:canTarget(source) then
		if e.state == "Hunt" and e.data.target ~= source then
			-- Keeps the nearer quarry.
			local current = e.data.target
			if current and e:canTarget(current) and e:distanceTo(current) < e:distanceTo(source) then
				e.data.lastHeard = os.clock()
				return
			end
		end
		hunt(e, source)
	end
end

function Lampshy.onAgitate(e, _position: Vector3)
	local nearest = e:nearestTarget()
	if nearest then
		hunt(e, nearest)
	end
end

function Lampshy.onBanish(e, model: Model, _killer: Player?)
	local position = model:GetPivot().Position
	for _, p in model:GetDescendants() do
		if p:IsA("BasePart") then
			p.Anchored = true
			p.CanCollide = false
			p.CanQuery = false
			if p.Name ~= "HumanoidRootPart" then
				p.Material = Enum.Material.Neon
				p.Color = Color3.fromRGB(226, 222, 206)
				p.Transparency = 0.3
			end
		end
	end
	local pale = Color3.fromRGB(230, 226, 210)
	Map.addGlow(position, cfg.glowRadius, cfg.glowTime, pale)
	task.delay(cfg.glowTime - 4, function()
		for _, p in model:GetDescendants() do
			if p:IsA("BasePart") then
				TweenService:Create(p, TweenInfo.new(4), { Transparency = 1 }):Play()
			end
		end
		task.delay(4, function()
			model:Destroy()
		end)
	end)
	for _, player in Players:GetPlayers() do
		local r = Crew.root(player)
		if r and (r.Position - position).Magnitude < 80 then
			Say.to(player, "[It folds up on itself and glows, pale, where it fell]", 4, "sound")
		end
	end
end

return Lampshy
]=] },
	{ service = {"ServerScriptService"}, path = {"Ashgrove", "Entities", "Registry"}, class = "ModuleScript", source = [=[
--[[
	Registry: every killable entity in the game, by id, plus the signals
	other systems listen to.

	  died(entity, position, killer)   a manifestation was killed (banished).
	                                   The Banshee treats this as a death.
	  formed(entity)                   it re-formed at its object.
]]

local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Signal = require(ReplicatedStorage:WaitForChild("Ashgrove"):WaitForChild("Signal"))

local Registry = {}

Registry.died = Signal.new()
Registry.formed = Signal.new()

local entities: { [string]: any } = {}
local order: { any } = {}

function Registry.add(entity: any)
	entities[entity.id] = entity
	table.insert(order, entity)
end

function Registry.get(id: string): any
	return entities[id]
end

function Registry.all(): { any }
	return order
end

-- The entity a part belongs to, if any (for bullets).
function Registry.fromPart(part: Instance): any
	local node: Instance? = part
	while node and node ~= workspace do
		local id = node:GetAttribute("EntityId")
		if id and node:IsA("Model") then
			return entities[id]
		end
		node = node.Parent
	end
	return nil
end

function Registry.activeInWing(wing: string): { any }
	local out = {}
	for _, e in order do
		if e.status == "active" and e.wing == wing then
			table.insert(out, e)
		end
	end
	return out
end

return Registry
]=] },
	{ service = {"ServerScriptService"}, path = {"Ashgrove", "Entities", "Rigs"}, class = "ModuleScript", source = [=[
--[[
	Rigs: the entities' bodies. Your own model is used when Models finds
	one (see Models.luau for where to put it); otherwise a greybox body
	built from blocks, so the game always runs.

	What a body gives the AI either way (Models prepares yours to match):
	  - Killable entities: a Model with a Humanoid and a "HumanoidRootPart"
	    whose -Z is the facing. Hittable parts carry a Hitbox attribute
	    ("Head" or "Body").
	  - Dullahan: the carried head is its own part, held by a joint whose
	    C0 the AI turns (so the head looks around) and that it breaks when
	    the head is shot out of his hands.
	  - Banshee: a Model whose pivot ("Root") is at her feet, plus the part
	    used as her face. No collisions; she never walks.
	Greybox sizes follow the art brief (studs; a player is about 5.5 tall).
]]

local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Config = require(ReplicatedStorage:WaitForChild("Ashgrove"):WaitForChild("Config"))

local Models = require(script.Parent.Parent.Models)

local Rigs = {}

local function newRig(name: string, rootSize: Vector3, hipHeight: number): (Model, Part, Humanoid)
	local model = Instance.new("Model")
	model.Name = name
	local root = Instance.new("Part")
	root.Name = "HumanoidRootPart"
	root.Size = rootSize
	root.Transparency = 1
	root.CanCollide = true
	root.CFrame = CFrame.new(0, hipHeight + rootSize.Y / 2, 0)
	root:SetAttribute("Hitbox", "Body")
	root.Parent = model
	model.PrimaryPart = root

	local humanoid = Instance.new("Humanoid")
	humanoid.RigType = Enum.HumanoidRigType.R15
	humanoid.HipHeight = hipHeight
	Models.configureHumanoid(humanoid)
	humanoid.Parent = model
	return model, root, humanoid
end

-- A part welded rigidly to the root, placed at root * offset.
local function limb(model: Model, root: BasePart, name: string, size: Vector3, offset: CFrame, colour: Color3, material: Enum.Material?, hitbox: string?): Part
	local p = Instance.new("Part")
	p.Name = name
	p.Size = size
	p.CFrame = root.CFrame * offset
	p.Color = colour
	p.Material = material or Enum.Material.SmoothPlastic
	p.CanCollide = false
	p.Massless = true
	p.TopSurface = Enum.SurfaceType.Smooth
	p.BottomSurface = Enum.SurfaceType.Smooth
	if hitbox then
		p:SetAttribute("Hitbox", hitbox)
	end
	local weld = Instance.new("WeldConstraint")
	weld.Part0 = root
	weld.Part1 = p
	weld.Parent = p
	p.Parent = model
	return p
end

Rigs.DULLAHAN_HEAD_OFFSET = Vector3.new(1.9, 1.7, -1.7)

export type HeadRig = { head: BasePart, headJoint: JointInstance }

-- The Dullahan: your model, or a greybox one: tall, headless, coated,
-- carrying a glowing head in the right hand and a whip of spine in the left.
function Rigs.dullahan(): (Model, BasePart, Humanoid, HeadRig)
	local custom, customRoot, customHumanoid, customHead = Models.creature("Dullahan")
	if custom and customRoot and customHumanoid then
		local head = customHead or customRoot
		if customHead then
			local glow = Instance.new("PointLight")
			glow.Range = Config.entities.Dullahan.headGlowRadius
			glow.Brightness = 1.2
			glow.Color = Color3.fromRGB(255, 226, 170)
			glow.Parent = customHead
		end
		return custom, customRoot, customHumanoid, { head = head, headJoint = Models.jointFor(custom, customRoot, head) }
	end

	local model, root, humanoid = newRig("Dullahan", Vector3.new(2, 2, 1), 2.5)
	local coat = Color3.fromRGB(28, 26, 28)
	local cloth = Color3.fromRGB(46, 42, 40)
	limb(model, root, "LegL", Vector3.new(1.2, 3.6, 1.2), CFrame.new(-0.75, -1.7, 0), cloth, nil, "Body")
	limb(model, root, "LegR", Vector3.new(1.2, 3.6, 1.2), CFrame.new(0.75, -1.7, 0), cloth, nil, "Body")
	limb(model, root, "Torso", Vector3.new(3, 3.6, 1.6), CFrame.new(0, 1.9, 0), cloth, nil, "Body")
	limb(model, root, "Coat", Vector3.new(3.4, 4.6, 1.9), CFrame.new(0, 1.1, 0.2), coat, Enum.Material.Fabric, "Body")
	limb(model, root, "Neck", Vector3.new(1.1, 0.4, 1.1), CFrame.new(0, 3.9, 0), Color3.fromRGB(70, 30, 26), nil, "Body")
	limb(model, root, "ArmL", Vector3.new(0.9, 3.4, 0.9), CFrame.new(-2, 1.7, 0), cloth, nil, "Body")
	limb(model, root, "ArmR", Vector3.new(0.9, 3, 0.9), CFrame.new(2, 2.6, -0.8) * CFrame.Angles(math.rad(-60), 0, 0), cloth, nil, "Body")
	limb(model, root, "Whip", Vector3.new(0.25, 4.2, 0.25), CFrame.new(-2.1, -1.9, -0.3), Color3.fromRGB(206, 196, 168), nil, "Body")

	local head = Instance.new("Part")
	head.Name = "CarriedHead"
	head.Shape = Enum.PartType.Ball
	head.Size = Vector3.one * 1.6
	head.Color = Color3.fromRGB(188, 176, 148)
	head.CanCollide = false
	head.Massless = true
	head:SetAttribute("Hitbox", "Head")
	head.CFrame = root.CFrame * CFrame.new(Rigs.DULLAHAN_HEAD_OFFSET)
	for _, side in { -0.3, 0.3 } do
		local eye = Instance.new("Part")
		eye.Name = "Eye"
		eye.Shape = Enum.PartType.Ball
		eye.Size = Vector3.one * 0.25
		eye.Material = Enum.Material.Neon
		eye.Color = Color3.fromRGB(255, 240, 190)
		eye.CanCollide = false
		eye.Massless = true
		eye:SetAttribute("Hitbox", "Head")
		eye.CFrame = head.CFrame * CFrame.new(side, 0.15, -0.72)
		local w = Instance.new("WeldConstraint")
		w.Part0 = head
		w.Part1 = eye
		w.Parent = eye
		eye.Parent = head
	end
	local grin = Instance.new("Part")
	grin.Name = "Grin"
	grin.Size = Vector3.new(0.8, 0.1, 0.1)
	grin.Color = Color3.fromRGB(20, 12, 10)
	grin.CanCollide = false
	grin.Massless = true
	grin:SetAttribute("Hitbox", "Head")
	grin.CFrame = head.CFrame * CFrame.new(0, -0.35, -0.7)
	local gw = Instance.new("WeldConstraint")
	gw.Part0 = head
	gw.Part1 = grin
	gw.Parent = grin
	grin.Parent = head
	local glow = Instance.new("PointLight")
	glow.Range = Config.entities.Dullahan.headGlowRadius
	glow.Brightness = 1.2
	glow.Color = Color3.fromRGB(255, 226, 170)
	glow.Parent = head

	local headWeld = Instance.new("Weld")
	headWeld.Name = "HeadWeld"
	headWeld.Part0 = root
	headWeld.Part1 = head
	headWeld.C0 = CFrame.new(Rigs.DULLAHAN_HEAD_OFFSET)
	headWeld.Parent = head
	head.Parent = model

	return model, root, humanoid, { head = head, headJoint = headWeld }
end

-- The Lamp-shy (PLACEHOLDER minor entity, decision #1): your model, or a
-- low, pale greybox crawler.
function Rigs.lampshy(): (Model, BasePart, Humanoid)
	local custom, customRoot, customHumanoid = Models.creature("Lampshy")
	if custom and customRoot and customHumanoid then
		return custom, customRoot, customHumanoid
	end
	local model, root, humanoid = newRig("Lampshy", Vector3.new(2, 1.4, 3), 0.3)
	local skin = Color3.fromRGB(200, 196, 186)
	limb(model, root, "Body", Vector3.new(1.8, 1.1, 3.6), CFrame.new(0, 0.1, 0), skin, nil, "Body")
	limb(model, root, "Head", Vector3.new(1.2, 0.9, 1.3), CFrame.new(0, 0.25, -2.3), skin, nil, "Body")
	limb(model, root, "Mouth", Vector3.new(0.8, 0.12, 0.05), CFrame.new(0, 0.1, -2.96), Color3.fromRGB(16, 10, 10), nil, "Body")
	for _, leg in {
		{ -1.3, -1.2, 35 },
		{ 1.3, -1.2, -35 },
		{ -1.3, 1.2, -35 },
		{ 1.3, 1.2, 35 },
	} do
		limb(model, root, "Leg", Vector3.new(0.3, 0.3, 2.4), CFrame.new(leg[1], -0.3, leg[2]) * CFrame.Angles(0, math.rad(leg[3]), math.rad(if leg[1] < 0 then 25 else -25)), skin, nil, "Body")
	end
	return model, root, humanoid
end

-- The Banshee: your model, or a greybox one, tall, still, robed in her
-- reserved colour. Anchored; she appears and disappears, she never walks.
-- Returns the model, her face (torch check) and where her keen comes from.
function Rigs.banshee(): (Model, BasePart, BasePart)
	local custom, customFace, customChest = Models.banshee()
	if custom and customFace and customChest then
		return custom, customFace, customChest
	end
	local model = Instance.new("Model")
	model.Name = "Banshee"
	local root = Instance.new("Part")
	root.Name = "Root"
	root.Anchored = true
	root.Transparency = 1
	root.Size = Vector3.one * 0.5
	root.CFrame = CFrame.new(0, 0, 0)
	root.CanCollide = false
	root.CanQuery = false
	root.CanTouch = false
	root.Parent = model
	model.PrimaryPart = root

	local colour = Config.banshee.colour
	local function add(name: string, size: Vector3, cf: CFrame, c: Color3, material: Enum.Material?): Part
		local p = Instance.new("Part")
		p.Name = name
		p.Anchored = true
		p.Size = size
		p.CFrame = cf
		p.Color = c
		p.Material = material or Enum.Material.SmoothPlastic
		p.CanCollide = false
		p.CanQuery = false
		p.CanTouch = false
		p.CastShadow = false
		p:SetAttribute("BaseTransparency", 0)
		p.Parent = model
		return p
	end
	add("Hem", Vector3.new(3.4, 1.2, 2.2), CFrame.new(0, 0.6, 0), colour, Enum.Material.Fabric)
	add("Robe", Vector3.new(2.8, 5.8, 1.8), CFrame.new(0, 3.5, 0), colour, Enum.Material.Fabric)
	add("Chest", Vector3.new(2.2, 2.4, 1.3), CFrame.new(0, 7.4, 0), colour, Enum.Material.Fabric)
	add("ArmL", Vector3.new(0.6, 3.2, 0.6), CFrame.new(-1.4, 6.6, -0.2) * CFrame.Angles(0, 0, math.rad(-8)), colour, Enum.Material.Fabric)
	add("ArmR", Vector3.new(0.6, 3.2, 0.6), CFrame.new(1.4, 6.6, -0.2) * CFrame.Angles(0, 0, math.rad(8)), colour, Enum.Material.Fabric)
	local pale = Color3.fromRGB(206, 206, 198)
	add("Face", Vector3.new(1.1, 1.35, 1.1), CFrame.new(0, 9.3, 0), pale)
	local dark = Color3.fromRGB(10, 10, 12)
	add("EyeL", Vector3.new(0.22, 0.14, 0.05), CFrame.new(-0.25, 9.5, -0.56), dark)
	add("EyeR", Vector3.new(0.22, 0.14, 0.05), CFrame.new(0.25, 9.5, -0.56), dark)
	add("Mouth", Vector3.new(0.3, 0.45, 0.05), CFrame.new(0, 8.95, -0.56), dark)
	local hair = Color3.fromRGB(206, 210, 204)
	add("HairBack", Vector3.new(1.3, 4.4, 0.4), CFrame.new(0, 7.8, 0.6), hair, Enum.Material.Fabric)
	add("HairL", Vector3.new(0.3, 3.6, 0.9), CFrame.new(-0.65, 8.2, -0.05), hair, Enum.Material.Fabric)
	add("HairR", Vector3.new(0.3, 3.6, 0.9), CFrame.new(0.65, 8.2, -0.05), hair, Enum.Material.Fabric)
	local light = Instance.new("PointLight")
	light.Color = colour
	light.Range = 12
	light.Brightness = 0.7
	local chest = model:FindFirstChild("Chest") :: BasePart
	light.Parent = chest
	return model, model:FindFirstChild("Face") :: BasePart, chest
end

return Rigs
]=] },
	{ service = {"ServerScriptService"}, path = {"Ashgrove", "Hooks"}, class = "ModuleScript", source = [=[
--[[
	Hooks: where Ashgrove meets the rest of your game.

	Nothing here is required: out of the box Ashgrove notices your gun on
	its own (see Shots). Wire these in when you want exact behaviour.

	----------------------------------------------------------------------
	YOUR GUN -> ASHGROVE. From your gun's SERVER code:

	    local Ashgrove = require(game.ServerScriptService.Ashgrove.Hooks)

	    -- a bullet hit something (call it for every hit; misses are fine
	    -- to skip). Ashgrove ignores parts that aren't its monsters.
	    Ashgrove.reportHit(player, hitPart, hitPosition)

	    -- a shot was fired, hit or miss: monsters hear it
	    Ashgrove.reportShot(player, muzzlePosition)

	    -- the player started reloading: their torch goes off meanwhile
	    Ashgrove.reportReload(player, reloadSeconds)

	    -- should this player be allowed to shoot right now? false while
	    -- they're down, taken by the Banshee, or busy (securing, reviving)
	    if not Ashgrove.canShoot(player) then return end

	----------------------------------------------------------------------
	ASHGROVE -> YOUR GAME. WIRE UP: replace the body of these.

	    Hooks.giveAmmo(player, rounds) -> boolean
	        Ammo pickups. Fill it in to give `rounds` to your gun and return
	        true, then set Hooks.ammoPickups = true below. Until then, ammo
	        pickups are left out of the map entirely.
]]

local Crew = require(script.Parent.Crew)
local Shots = require(script.Parent.Shots)

local Hooks = {}

-- Your gun calls these. ---------------------------------------------------

function Hooks.reportHit(player: Player, hitPart: BasePart, hitPosition: Vector3?)
	Shots.reportHit(player, hitPart, hitPosition)
end

function Hooks.reportShot(player: Player, muzzlePosition: Vector3?)
	Shots.reportShot(player, muzzlePosition)
end

function Hooks.reportReload(player: Player, reloadSeconds: number?)
	Shots.reportReload(player, reloadSeconds)
end

function Hooks.canShoot(player: Player): boolean
	return Crew.isActive(player) and not Crew.isCommitting(player)
end

-- WIRE UP. ----------------------------------------------------------------

-- WIRE UP: give `rounds` of ammo to your gun. Return true when you do.
function Hooks.giveAmmo(_player: Player, _rounds: number): boolean
	return false
end

-- WIRE UP: set to true once giveAmmo works, and ammo pickups appear.
Hooks.ammoPickups = false

return Hooks
]=] },
	{ service = {"ServerScriptService"}, path = {"Ashgrove", "House"}, class = "ModuleScript", source = [=[
--[[
	House: Ashgrove House, Story 1. Builds the layout the gameplay reads
	(walls, floors, zones, markers, interactives), then hands over to
	Dressing for everything that makes it look like a house: panelling,
	furniture, chandeliers, the roofs, the grounds, the cliff and the sea.

	Boot builds it at runtime if the workspace has no "AshgroveHouse". To
	see it (and edit it) in Studio before pressing Play, run this in the
	Command Bar:

	    require(game.ServerScriptService.Ashgrove.House).build()

	Once it exists in the place, Boot uses yours and never rebuilds it.
	Move furniture, swap pieces for the art brief's AH_Kit_* / AH_Prop_*
	models, restyle anything in Geometry: the gameplay never looks at it.
	Keep Zones, Markers and Interact (they're what the game reads), then
	run tools/check_greybox.luau to catch anything you've blocked.

	Layout (studs; 1 stud = 0.28 m; ground-floor top at y = 0; +X is east,
	towards the cliff):

	    Van and drive    x -160..-116   the hub and first sanctuary
	    Entrance hall    x  -60..-10    z -30..30, 24 high, the first crew's camp
	    Portrait gallery x  -10..110    z -30..-8, 20 high, 120-stud sight line
	    (courtyard)      x  -10..110    z  -8..8, closed off
	    Servants' wing   x  -10..110    z   8..30, 12 high
	        corridor z 8..14; kitchen x -10..30; scullery 30..60 (stairs down);
	        housekeeper 60..85; servants' hall 85..110
	    Cellar vault     x   20..80     z -20..30, floor at y = -16
	    Cliff edge       x  130, sea far below
	    Upper floor, study, cliff stair: built shut, for later stories

	What the systems read:
	    Zones/*     invisible boxes. Attributes: Wing, Room, Sanctuary,
	                Exterior, Priority, PoweredBy
	    Markers/*   invisible parts named Spawn_*, Dullahan_*, Lampshy_*,
	                Body_*, BansheeKeen_<Wing>_*
	    Interact/   Notes, Objects, Crates, Rites, Doors, Lamps, Pickups,
	                BellBoard, Glows
]]

