	zone("ServantsHall", 85, 110, -1, 13, 14, 30, { Wing = "ServantsWing", Room = "ServantsHall", Priority = 2 })
	zone("Vault", 20, 80, -17, -1, -20, 30, { Wing = "Vault", Room = "Vault", Priority = 3 })

	Dressing.dress(root)

	root.WorldPivot = CFrame.new(0, 0, 0)
	root.Parent = workspace
	return root
end

return House
