	{ service = {"ServerScriptService"}, path = {"Ashgrove", "Reading"}, class = "ModuleScript", source = [=[
--[[
	Reading: notes, catalogue cards and voice memos. A part with a NoteId
	attribute gets a "Read" prompt that opens the note on that player's
	screen (text in ReplicatedStorage.Ashgrove.Notes).

	RequiresMourning notes can only be read while the Banshee grieves over
	them (Banshee calls Reading.reveal); once revealed they stay readable.
]]

local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Shared = ReplicatedStorage:WaitForChild("Ashgrove")
local Net = require(Shared:WaitForChild("Net"))
local Notes = require(Shared:WaitForChild("Notes"))
local Signal = require(Shared:WaitForChild("Signal"))

local Map = require(script.Parent.Map)

local Reading = {}

Reading.read = Signal.new() -- (noteId, player)

local prompts: { [string]: ProximityPrompt } = {}
local readBy: { [string]: { [Player]: boolean } } = {}

function Reading.reveal(noteId: string)
	local prompt = prompts[noteId]
	if prompt then
		prompt.Enabled = true
	end
end

function Reading.hasBeenRead(noteId: string): boolean
	return readBy[noteId] ~= nil and next(readBy[noteId]) ~= nil
end

function Reading.setup()
	for _, p in Map.interact("Notes"):GetChildren() do
		local noteId = p:GetAttribute("NoteId")
		if p:IsA("BasePart") and noteId then
			local note = Notes[noteId]
			local prompt = Instance.new("ProximityPrompt")
			prompt.ActionText = if p.Size.Y > 0.2 then "Play" else "Read"
			prompt.ObjectText = if note then note.title else noteId
			prompt.HoldDuration = 0
			prompt.MaxActivationDistance = 7
			prompt.RequiresLineOfSight = false
			prompt.Enabled = p:GetAttribute("RequiresMourning") ~= true
			prompt.Parent = p
			prompts[noteId] = prompt
			prompt.Triggered:Connect(function(player)
				Net.event("Note"):FireClient(player, noteId)
				readBy[noteId] = readBy[noteId] or {}
				readBy[noteId][player] = true
				Reading.read:Fire(noteId, player)
			end)
		end
	end
end

return Reading
]=] },
	{ service = {"ServerScriptService"}, path = {"Ashgrove", "Retrieval"}, class = "ModuleScript", source = [=[
--[[
	Retrieval: the objective grammar. Each story is a list of collection
	objects to secure where they're found.

	An object part has ObjectId, Label, Securable and (optionally)
	EntityId. Securing is a committed action of Config.commit.secure
	seconds, or secureWhileEntityActive if its entity is up and about:
	kill it first and the window opens. Securing removes the entity for
	the rest of the story and closes the object's warded crate.

	Non-securable objects (the sealed box) can only be inspected.
]]

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local TweenService = game:GetService("TweenService")

local Shared = ReplicatedStorage:WaitForChild("Ashgrove")
local Audio = require(Shared:WaitForChild("Audio"))
local Config = require(Shared:WaitForChild("Config"))
local Signal = require(Shared:WaitForChild("Signal"))

local Crew = require(script.Parent.Crew)
local Map = require(script.Parent.Map)
local Registry = require(script.Parent.Entities.Registry)
local Say = require(script.Parent.Say)

local Retrieval = {}

Retrieval.secured = Signal.new() -- (objectId, player)
Retrieval.inspected = Signal.new() -- (objectId, player)

local objects: { [string]: BasePart } = {}
local done: { [string]: boolean } = {}
local enabled: { [string]: boolean } = {}

function Retrieval.isDone(objectId: string): boolean
	return done[objectId] == true
end

function Retrieval.setEnabled(objectId: string, on: boolean)
	enabled[objectId] = on
	local p = objects[objectId]
	local prompt = p and p:FindFirstChildOfClass("ProximityPrompt")
	if prompt and not done[objectId] then
		prompt.Enabled = on
	end
end

local function closeCrate(objectId: string)
	for _, crate in Map.interact("Crates"):GetChildren() do
		if crate:GetAttribute("CrateFor") == objectId then
			local lid = crate:FindFirstChild("Lid")
			if lid and lid:IsA("BasePart") then
				lid.Transparency = 0
				lid.CanCollide = true
			end
		end
	end
end

local function secure(objectId: string, player: Player?)
	if done[objectId] then
		return
	end
	done[objectId] = true
	local p = objects[objectId]
	local prompt = p:FindFirstChildOfClass("ProximityPrompt")
	if prompt then
		prompt.Enabled = false
	end
	TweenService:Create(p, TweenInfo.new(0.6), { Transparency = 1 }):Play()
	p.CanCollide = false
	p.CanQuery = false
	closeCrate(objectId)
	Audio.play("secure", p, 0.7)
	local entityId = p:GetAttribute("EntityId")
	local entity = entityId and Registry.get(entityId)
	if entity then
		entity:secure()
	end
	Say.all(`{p:GetAttribute("Label")} secured.`, 4, "story")
	Retrieval.secured:Fire(objectId, player)
end

-- Studio debug: secure an object as if someone had done it.
function Retrieval.forceSecure(objectId: string)
	if objects[objectId] then
		secure(objectId, nil)
	end
end

function Retrieval.setup()
	for _, p in Map.interact("Objects"):GetChildren() do
		if p:IsA("BasePart") and p:GetAttribute("ObjectId") then
			local objectId = p:GetAttribute("ObjectId") :: string
			objects[objectId] = p
			local securable = p:GetAttribute("Securable") == true
			local prompt = Instance.new("ProximityPrompt")
			prompt.ActionText = if securable then "Secure" else "Inspect"
			prompt.ObjectText = p:GetAttribute("Label") or objectId
			prompt.HoldDuration = 0.25
			prompt.MaxActivationDistance = 8
			prompt.RequiresLineOfSight = false
			prompt.Enabled = false
			prompt.Parent = p
			prompt.Triggered:Connect(function(player)
				if done[objectId] or not enabled[objectId] then
					return
				end
				if not securable then
					done[objectId] = true
					prompt.Enabled = false
					Retrieval.inspected:Fire(objectId, player)
					return
				end
				local entityId = p:GetAttribute("EntityId")
				local entity = entityId and Registry.get(entityId)
				local busy = entity ~= nil and entity.status == "active"
				local seconds = if busy then Config.commit.secureWhileEntityActive else Config.commit.secure
				if busy then
					Say.to(player, "It's still up. This will take longer.", 3, "hint")
				end
				Crew.commit(player, seconds, `Securing {prompt.ObjectText}`, function()
					secure(objectId, player)
				end)
			end)
		end
	end
end

return Retrieval
]=] },
	{ service = {"ServerScriptService"}, path = {"Ashgrove", "Rites"}, class = "ModuleScript", source = [=[
--[[
	Rites: the wake custom that answers a keen.

	A rite site is a Model under Interact/Rites with a Wing attribute and
	three step parts (RiteStep = "clock" | "mirror" | "window"). Its prompts
	only work while the Banshee is keening in that wing. Each step is a
	short committed action; when all three are done, Rites.completed fires
	and the Banshee is answered.

	Each site keeps the custom once. The room stays changed afterwards
	(the clock stopped, the mirror covered, the window open).
]]

local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Shared = ReplicatedStorage:WaitForChild("Ashgrove")
local Audio = require(Shared:WaitForChild("Audio"))
local Config = require(Shared:WaitForChild("Config"))
local Signal = require(Shared:WaitForChild("Signal"))

local Crew = require(script.Parent.Crew)
local Map = require(script.Parent.Map)
local Say = require(script.Parent.Say)

local Rites = {}

Rites.completed = Signal.new() -- (siteName, wing, player)

local STEP_TEXT = {
	clock = { action = "Stop the clock", done = "The clock stops." },
	mirror = { action = "Cover the mirror", done = "The glass is covered." },
	window = { action = "Open the window", done = "The window is open." },
}

type Site = {
	model: Model,
	wing: string,
	used: boolean,
	steps: { [BasePart]: boolean },
}

local sites: { Site } = {}

local function applyStep(part: BasePart, step: string)
	if step == "mirror" then
		local cloth = part:FindFirstChild("Cloth")
		if cloth and cloth:IsA("BasePart") then
			cloth.Transparency = 0
		end
	elseif step == "window" then
		part.Transparency = 0.95
		part.CanCollide = false
	elseif step == "clock" then
		part:SetAttribute("Stopped", true)
	end
end

local function siteDone(site: Site): boolean
	for _, isDone in site.steps do
		if not isDone then
			return false
		end
	end
	return true
end

function Rites.hasUnusedSite(wing: string): boolean
	for _, site in sites do
		if site.wing == wing and not site.used then
			return true
		end
	end
	return false
end

-- Turns the prompts on (during a keen in that wing) or off.
function Rites.setActive(wing: string, on: boolean)
	for _, site in sites do
		if site.wing == wing then
			for part, isDone in site.steps do
				local prompt = part:FindFirstChildOfClass("ProximityPrompt")
				if prompt then
					prompt.Enabled = on and not site.used and not isDone
				end
			end
		end
	end
end

function Rites.setup()
	for _, model in Map.interact("Rites"):GetChildren() do
		if model:IsA("Model") then
			local site: Site = {
				model = model,
				wing = model:GetAttribute("Wing") or "",
				used = false,
				steps = {},
			}
			table.insert(sites, site)
			for _, part in model:GetChildren() do
				local step = part:GetAttribute("RiteStep")
				if part:IsA("BasePart") and step and STEP_TEXT[step] then
					site.steps[part] = false
					local prompt = Instance.new("ProximityPrompt")
					prompt.ActionText = STEP_TEXT[step].action
					prompt.ObjectText = "The wake custom"
					prompt.HoldDuration = 0.2
					prompt.MaxActivationDistance = 8
					prompt.RequiresLineOfSight = false
					prompt.Enabled = false
					prompt.Parent = part
					prompt.Triggered:Connect(function(player)
						if site.used or site.steps[part] then
							return
						end
						Crew.commit(player, Config.commit.rite, STEP_TEXT[step].action, function()
							if site.used or site.steps[part] then
								return
							end
							site.steps[part] = true
							prompt.Enabled = false
							applyStep(part, step)
							Audio.play("riteStep", part, 0.6)
							Say.near(part.Position, 40, STEP_TEXT[step].done, 3, "story")
							if siteDone(site) then
								site.used = true
								Rites.completed:Fire(model.Name, site.wing, player)
							end
						end)
					end)
				end
			end
		end
	end
end

return Rites
]=] },
	{ service = {"ServerScriptService"}, path = {"Ashgrove", "Say"}, class = "ModuleScript", source = [=[
--[[
	Say: on-screen captions. Every sound that carries information has one,
	so the game reads correctly with no audio and for deaf players.

	Styles: "sound" for [bracketed sound captions], "story" for lines the
	player should notice, "hint" for teaching text.
]]

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Net = require(ReplicatedStorage:WaitForChild("Ashgrove"):WaitForChild("Net"))

local captionRemote = Net.event("Caption")

local Say = {}

function Say.to(player: Player, text: string, seconds: number?, style: string?)
	captionRemote:FireClient(player, text, seconds or 4, style or "story")
end

function Say.all(text: string, seconds: number?, style: string?)
	captionRemote:FireAllClients(text, seconds or 4, style or "story")
end

-- Everyone whose character is within `radius` of `position`.
function Say.near(position: Vector3, radius: number, text: string, seconds: number?, style: string?)
	for _, player in Players:GetPlayers() do
		local character = player.Character
		local root = character and character:FindFirstChild("HumanoidRootPart")
		if root and ((root :: BasePart).Position - position).Magnitude <= radius then
			Say.to(player, text, seconds, style)
		end
	end
end

function Say.except(skip: Player, text: string, seconds: number?, style: string?)
	for _, player in Players:GetPlayers() do
		if player ~= skip then
			Say.to(player, text, seconds, style)
		end
	end
end

return Say
]=] },
	{ service = {"ServerScriptService"}, path = {"Ashgrove", "Shots"}, class = "ModuleScript", source = [=[
--[[
	Shots: notices YOUR gun hitting Ashgrove's monsters, without needing to
	know how your gun works.

	Three sources, combined (Config.integration.hitDetection):
	  1. Click reports. Every left click with a tool out sends the camera's
	     ray here. That's the gunshot NOISE (always), and the aim used to
	     work out which body part was hit.
	  2. Damage. Monster Humanoids have huge health; when your gun damages
	     one, that's the confirmed hit. The part is found along the
	     shooter's last click ray (the Dullahan's head matters), and health
	     is topped back up straight away.
	  3. Hooks.reportHit(player, part, position) from your gun's own code.
	     Exact. Once it's been used, 1 and 2 stop counting hits.

	In "auto" mode, if three click rays hit a monster and none of them ever
	came with damage, your gun clearly doesn't damage Humanoids: Shots
	switches to "click" mode by itself and says so in the Output window.

	Click rays don't know about your wobble. For hits that match your
	bullets exactly, wire Hooks.reportHit.
]]

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Shared = ReplicatedStorage:WaitForChild("Ashgrove")
local Config = require(Shared:WaitForChild("Config"))
local Net = require(Shared:WaitForChild("Net"))

local Crew = require(script.Parent.Crew)
local Map = require(script.Parent.Map)
local Noise = require(script.Parent.Noise)
local Registry = require(script.Parent.Entities.Registry)

local cfg = Config.integration

local Shots = {}

type Click = { origin: Vector3, direction: Vector3, at: number }

local mode: string = cfg.hitDetection
local lastClick: { [Player]: Click } = {}
local lastNoise: { [Player]: number } = {}
local damageEverSeen = false
local hooksUsed = false
local undamagedClickHits = 0

local function rayParams(): RaycastParams
	local params = RaycastParams.new()
	params.FilterType = Enum.RaycastFilterType.Exclude
	local ignore: { Instance } = { Map.interact("Glows") }
	for _, player in Players:GetPlayers() do
		if player.Character then
			table.insert(ignore, player.Character)
		end
	end
	params.FilterDescendantsInstances = ignore
	return params
end

-- First thing along a ray; returns the entity if it's one of ours.
local function castFor(origin: Vector3, direction: Vector3): (any, BasePart?, Vector3?)
	local result = workspace:Raycast(origin, direction.Unit * cfg.clickRange, rayParams())
	if not result then
		return nil, nil, nil
	end
	return Registry.fromPart(result.Instance), result.Instance :: BasePart, result.Position
end

local function apply(entity, part: BasePart, shooter: Player, position: Vector3)
	if entity and entity.status == "active" then
		entity:shot(part, shooter, position)
	end
end

------------------------------------------------------------------ for Hooks

function Shots.reportShot(player: Player, origin: Vector3?)
	local now = os.clock()
	if now - (lastNoise[player] or 0) < 0.15 then
		return
	end
	lastNoise[player] = now
	local head = Crew.head(player)
	local at = origin or (if head then head.Position else nil)
	if at then
		Noise.emit(at, cfg.gunshotNoise, "gunshot", player)
	end
end

function Shots.reportHit(player: Player, part: BasePart, position: Vector3?)
	hooksUsed = true
	local entity = Registry.fromPart(part)
	if entity then
		apply(entity, part, player, position or part.Position)
	end
end

function Shots.reportReload(player: Player, seconds: number?)
	local duration = seconds or cfg.reloadTorchOff
	if duration > 0 then
		Crew.suppressFlashlight(player, duration)
	end
end

------------------------------------------------------------------ damage

-- Entity calls this when its Humanoid loses health.
function Shots.onDamaged(entity)
	damageEverSeen = true
	if hooksUsed or mode == "hooks" or mode == "click" then
		return
	end
	-- Who did it: the most recent click whose ray reaches this entity.
	local now = os.clock()
	local bestPlayer, bestPart, bestPos, bestAt = nil, nil, nil, -math.huge
	for player, click in lastClick do
		if now - click.at < 0.8 and click.at > bestAt then
			local hitEntity, part, position = castFor(click.origin, click.direction)
			if hitEntity == entity and part then
				bestPlayer, bestPart, bestPos, bestAt = player, part, position, click.at
			end
		end
	end
	if not bestPlayer then
		-- Shot from an angle the click ray can't explain (your wobble): blame
		-- the nearest player with a tool out, and call it a body hit.
		local root = entity.root
		local nearest, distance = nil, math.huge
		for _, player in Players:GetPlayers() do
			local character = player.Character
			local r = Crew.root(player)
			if character and r and root and character:FindFirstChildOfClass("Tool") then
				local d = (r.Position - root.Position).Magnitude
				if d < distance then
					nearest, distance = player, d
				end
			end
		end
		if nearest and root then
			apply(entity, root, nearest, root.Position)
		end
		return
	end
	apply(entity, bestPart :: BasePart, bestPlayer, bestPos :: Vector3)
end

------------------------------------------------------------------ clicks

local function onClick(player: Player, origin: any, direction: any)
	if typeof(origin) ~= "Vector3" or typeof(direction) ~= "Vector3" or direction.Magnitude < 0.5 then
		return
	end
	local head = Crew.head(player)
	if not head or (origin - head.Position).Magnitude > 10 or not Crew.isActive(player) then
		return
	end
	local character = player.Character
	if not character or not character:FindFirstChildOfClass("Tool") then
		return
	end
	local now = os.clock()
	lastClick[player] = { origin = origin, direction = direction.Unit, at = now }
	Shots.reportShot(player, origin)

	if hooksUsed or mode == "hooks" or mode == "damage" then
		return
	end
	local entity, part, position = castFor(origin, direction)
	if not entity or not part then
		return
	end
	if mode == "click" then
		apply(entity, part, player, position :: Vector3)
		return
	end
	-- "auto": wait a moment to see whether the gun's own damage arrives.
	task.delay(0.5, function()
		if damageEverSeen or hooksUsed or mode ~= "auto" then
			return
		end
		undamagedClickHits += 1
		if undamagedClickHits >= 3 then
			mode = "click"
			warn("[Ashgrove] Your gun doesn't seem to damage Humanoids, so hits now come from click rays. For exact hits, call Hooks.reportHit from your gun (see ServerScriptService.Ashgrove.Hooks).")
			apply(entity, part, player, position :: Vector3)
		end
	end)
end

function Shots.start()
	Net.event("Shot").OnServerEvent:Connect(onClick)
	Net.event("Reload").OnServerEvent:Connect(function(player)
		local character = player.Character
		if character and character:FindFirstChildOfClass("Tool") then
			Shots.reportReload(player)
		end
	end)
	Players.PlayerRemoving:Connect(function(player)
		lastClick[player] = nil
		lastNoise[player] = nil
	end)
end

return Shots
]=] },
	{ service = {"ServerScriptService"}, path = {"Ashgrove", "Storm"}, class = "ModuleScript", source = [=[
--[[
	Storm: the night's lighting, rain and lightning, and how they change.

	- Lightning is gameplay light. Flashes come at irregular intervals and
	  count as "lit" for Storm.flashWindow seconds (the Lamp-shy freezes).
	- The storm builds: each secured object raises the level. At
	  Config.storm.powerCutLevel the hall's work lamp fails and the hall
	  stops being a sanctuary.
	- When the Banshee keens, the storm goes silent: no rain, no lightning.
	  That silence is the warning.
]]

local Lighting = game:GetService("Lighting")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local SoundService = game:GetService("SoundService")
local TweenService = game:GetService("TweenService")

local Shared = ReplicatedStorage:WaitForChild("Ashgrove")
local Audio = require(Shared:WaitForChild("Audio"))
local Config = require(Shared:WaitForChild("Config"))
local Net = require(Shared:WaitForChild("Net"))

local Map = require(script.Parent.Map)
local Say = require(script.Parent.Say)

local Storm = {}

Storm.level = 0

local silenced = false
local flashUntil = 0
local rain: Sound? = nil

local function setupLighting()
	Lighting.ClockTime = 1
	Lighting.Brightness = 0.3
	Lighting.Ambient = Color3.fromRGB(10, 10, 14)
	Lighting.OutdoorAmbient = Color3.fromRGB(26, 30, 38)
	Lighting.EnvironmentDiffuseScale = 0
	Lighting.EnvironmentSpecularScale = 0.2
	Lighting.GlobalShadows = true
	Lighting.ExposureCompensation = -0.2
	Lighting.FogColor = Color3.fromRGB(20, 24, 30)
	Lighting.FogStart = 0
	Lighting.FogEnd = 260

	for _, child in Lighting:GetChildren() do
		if child:IsA("Sky") or child:IsA("Atmosphere") then
			child:Destroy()
		end
	end
	local sky = Instance.new("Sky")
	sky.StarCount = 0
	sky.CelestialBodiesShown = false
	sky.Parent = Lighting
	local atmosphere = Instance.new("Atmosphere")
	atmosphere.Density = 0.42
	atmosphere.Offset = 0.1
	atmosphere.Color = Color3.fromRGB(40, 46, 56)
	atmosphere.Decay = Color3.fromRGB(20, 22, 28)
	atmosphere.Glare = 0
	atmosphere.Haze = 2
	atmosphere.Parent = Lighting
end

function Storm.isFlashing(): boolean
	return os.clock() < flashUntil
end

function Storm.isSilenced(): boolean
	return silenced
end

local function flash()
	flashUntil = os.clock() + Config.storm.flashWindow
	Net.event("Lightning"):FireAllClients(1)
	task.delay(1 + math.random() * 2.5, function()
		if silenced then
			return
		end
		Audio.play("thunder", SoundService, 0.7)
		Say.all("[Thunder]", 2, "sound")
	end)
end

-- Dressing's living details: failing bulbs and candles (Flicker =
-- "bulb"), the lit attic window that sometimes goes dark (Flicker =
-- "window"), and the lighthouse beam (Spin).
local function animateDetails()
	local bulbs, windows, spinners = {}, {}, {}
	for _, d in Map.root():GetDescendants() do
		if d:IsA("Light") then
			local kind = d:GetAttribute("Flicker")
			if kind == "bulb" then
				table.insert(bulbs, { light = d, base = d.Brightness })
			elseif kind == "window" then
				table.insert(windows, { light = d, base = d.Brightness })
			end
		elseif d:IsA("BasePart") and d:GetAttribute("Spin") then
			table.insert(spinners, d)
		end
	end
	task.spawn(function()
		while true do
			task.wait(0.08)
			for _, b in bulbs do
				local r = math.random()
				b.light.Brightness = if r < 0.06 then 0 elseif r < 0.2 then b.base * 0.4 else b.base
			end
		end
	end)
	for _, w in windows do
		task.spawn(function()
			while true do
				w.light.Enabled = true
				task.wait(20 + math.random() * 40)
				w.light.Enabled = false
				task.wait(4 + math.random() * 10)
			end
		end)
	end
	if #spinners > 0 then
		task.spawn(function()
			local angle = 0
			while true do
				local dt = task.wait(0.05)
				angle += dt * 0.6
				for _, beam in spinners do
					local centre = beam:GetAttribute("SpinCentre")
					if typeof(centre) == "Vector3" then
						beam.CFrame = CFrame.new(centre) * CFrame.Angles(0, angle, 0) * CFrame.new(0, 0, -beam.Size.Z / 2)
					end
				end
			end
		end)
	end
end

function Storm.start()
	setupLighting()
	animateDetails()
	rain = Audio.loop("rain", SoundService, Config.storm.rainVolume[0])
	task.spawn(function()
		while true do
			local range = Config.storm.lightning[math.min(Storm.level, 3)]
			task.wait(range.min + math.random() * (range.max - range.min))
			if not silenced then
				flash()
			end
		end
	end)
end

function Storm.silence(on: boolean)
	silenced = on
	if rain then
		local volume = if on then 0 else Config.storm.rainVolume[math.min(Storm.level, 3)]
		TweenService:Create(rain, TweenInfo.new(if on then 1.5 else 4), { Volume = volume }):Play()
	end
end

-- Turns off every lamp in a power group. Zones powered by that group stop
-- being sanctuaries.
function Storm.cutPower(group: string)
	for _, lamp in Map.interact("Lamps"):GetChildren() do
		if lamp:GetAttribute("PowerGroup") == group then
			lamp:SetAttribute("Powered", false)
			for _, light in lamp:GetDescendants() do
				if light:IsA("Light") then
					light.Enabled = false
				end
			end
			if lamp:IsA("BasePart") then
				lamp.Material = Enum.Material.SmoothPlastic
				lamp.Color = Color3.fromRGB(40, 36, 30)
			end
		end
	end
	for _, zonePart in Map.zonesWithAttribute("PoweredBy", group) do
		zonePart:SetAttribute("Sanctuary", false)
	end
end

function Storm.escalate()
	Storm.level += 1
	if rain and not silenced then
		TweenService:Create(rain, TweenInfo.new(6), { Volume = Config.storm.rainVolume[math.min(Storm.level, 3)] }):Play()
	end
	Say.all("[The storm gets worse]", 3, "sound")
	if Storm.level == Config.storm.powerCutLevel then
		Storm.cutPower("Hall")
		Say.all("The work lamp in the hall gutters out. The hall isn't safe any more.", 6, "story")
	end
end

return Storm
