		TextSize = 14,
	}, battery)
	goldLabel = text({
		Name = "Gold",
		AnchorPoint = Vector2.new(0, 1),
		Position = UDim2.new(0, 28, 1, -64),
		Size = UDim2.fromOffset(240, 20),
		TextXAlignment = Enum.TextXAlignment.Left,
		TextColor3 = Color3.fromRGB(214, 180, 90),
		TextSize = 16,
