	text({
		Size = UDim2.fromScale(1, 1),
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = Enum.TextYAlignment.Top,
		TextSize = 18,
		Text = table.concat({
			"WASD   move",
			"Shift  sprint (loud)",
			"C      crouch (silent)",
			"F      torch",
			"R      reload (your torch goes off)",
			"G      raise the gold, if you have it",
			"E      interact",
			"Q      put a note down",
			"H      this help",
			"",
			"Crouch near her while she grieves.",
		}, "\n"),
	}, helpPanel)
end

------------------------------------------------------------------ calls

local captionOrder = 0
function Hud.caption(message: string, seconds: number?, style: string?)
	captionOrder += 1
	local colour = if style == "sound" then DIM elseif style == "hint" then Color3.fromRGB(180, 196, 210) else PAPER
	local label = text({
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Text = message,
		TextColor3 = colour,
		TextSize = if style == "sound" then 19 else 21,
		Font = if style == "sound" then Enum.Font.SourceSansItalic else BODY_FONT,
		TextStrokeTransparency = 0.6,
		LayoutOrder = captionOrder,
	}, captionsFrame)
	local labels = {}
	for _, child in captionsFrame:GetChildren() do
		if child:IsA("TextLabel") then
			table.insert(labels, child)
		end
	end
	table.sort(labels, function(a, b)
		return a.LayoutOrder < b.LayoutOrder
	end)
	while #labels > 5 do
		local oldest = table.remove(labels, 1)
		if oldest then
			oldest:Destroy()
		end
	end
	task.delay(seconds or 4, function()
		if label.Parent then
			local fade = TweenService:Create(label, TweenInfo.new(0.8), { TextTransparency = 1, TextStrokeTransparency = 1 })
			fade:Play()
			fade.Completed:Wait()
			label:Destroy()
		end
	end)
end

function Hud.setObjectives(list: { { text: string, done: boolean? } })
	for _, child in objectivesFrame:GetChildren() do
		if child:IsA("TextLabel") then
			child:Destroy()
		end
	end
	for i, objective in list do
		text({
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			Text = (if objective.done then "x  " else "-  ") .. objective.text,
			TextColor3 = if objective.done then DIM else PAPER,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextSize = 18,
			TextStrokeTransparency = 0.7,
			LayoutOrder = i,
		}, objectivesFrame)
	end
end

function Hud.chapter(title: string, subtitle: string)
	chapterTitle.Text = title
	chapterSub.Text = subtitle
	for _, label in { chapterTitle, chapterSub } do
		label.TextTransparency = 1
		TweenService:Create(label, TweenInfo.new(1.5), { TextTransparency = 0 }):Play()
	end
	task.delay(5, function()
		for _, label in { chapterTitle, chapterSub } do
			TweenService:Create(label, TweenInfo.new(2), { TextTransparency = 1 }):Play()
		end
	end)
end

function Hud.showNote(noteId: string)
	local note = Notes[noteId]
	if not note then
		return
	end
	noteTitle.Text = note.title
	noteBody.Text = note.body
	noteScroll.CanvasPosition = Vector2.zero
	notePanel.Visible = true
	local character = player.Character
	local root = character and character:FindFirstChild("HumanoidRootPart")
	noteOpenAt = if root then (root :: BasePart).Position else nil
end

function Hud.closeNote()
	notePanel.Visible = false
	noteOpenAt = nil
end

function Hud.isNoteOpen(): boolean
	return notePanel.Visible
end

function Hud.toggleHelp()
	helpPanel.Visible = not helpPanel.Visible
end

function Hud.keen(state: string, info: { [string]: any })
	if state == "start" then
		keenInfo = info
		keenLabel.Visible = true
		keenLabel.Text = if info.target == player.UserId then "She is facing you." else `She is facing {info.targetName}.`
	else
		keenInfo = nil
		keenLabel.Visible = false
		TweenService:Create(keenShade, TweenInfo.new(2), { BackgroundTransparency = 1 }):Play()
	end
end

-- Full-screen states: "wipe", "end", "clear".
function Hud.screen(kind: string, message: string)
	screenKind = if kind == "clear" then "" else kind
	if kind == "clear" then
		TweenService:Create(overlay, TweenInfo.new(1.5), { BackgroundTransparency = 1 }):Play()
		TweenService:Create(overlayText, TweenInfo.new(1), { TextTransparency = 1 }):Play()
		return
	end
	overlayText.Text = message
	TweenService:Create(overlay, TweenInfo.new(if kind == "end" then 4 else 1.5), { BackgroundTransparency = 0 }):Play()
	TweenService:Create(overlayText, TweenInfo.new(2), { TextTransparency = 0 }):Play()
end

------------------------------------------------------------------ per frame

local function update()
	local battery = (player:GetAttribute("Battery") or 0) / Config.flashlight.maxBattery
	batteryFill.Size = UDim2.fromScale(math.clamp(battery, 0, 1), 1)
	batteryFill.BackgroundTransparency = if player:GetAttribute("LightOn") then 0 else 0.6

	if player:GetAttribute("HasGold") then
		goldLabel.Visible = true
		local readyAt = player:GetAttribute("WardReadyAt") or 0
		local wait = readyAt - workspace:GetServerTimeNow()
		goldLabel.Text = if player:GetAttribute("WardRaised")
			then "GOLD raised"
			elseif wait > 0 then `GOLD  {math.ceil(wait)}s`
			else "GOLD  [G]"
	else
		goldLabel.Visible = false
	end

	local label = player:GetAttribute("CommitLabel")
	if label then
		commitFrame.Visible = true
		commitLabel.Text = label
		local length = player:GetAttribute("CommitLength") or 1
		local ends = player:GetAttribute("CommitEnds") or 0
		local progress = 1 - math.clamp((ends - workspace:GetServerTimeNow()) / length, 0, 1)
		commitFill.Size = UDim2.fromScale(progress, 1)
	else
		commitFrame.Visible = false
	end

	-- The one she faces sees the dark close in as the window runs out.
	if keenInfo and keenInfo.target == player.UserId then
		local left = math.clamp((keenInfo.endsAt - workspace:GetServerTimeNow()) / keenInfo.length, 0, 1)
		keenShade.BackgroundTransparency = 0.45 + 0.55 * left
	end

	local hits = player:GetAttribute("Hits") or 0
	if hits > lastHits then
		hurtFlash.BackgroundTransparency = 0.55
		TweenService:Create(hurtFlash, TweenInfo.new(0.8), { BackgroundTransparency = 1 }):Play()
	end
	lastHits = hits

	if screenKind ~= "wipe" and screenKind ~= "end" then
		if player:GetAttribute("Taken") then
			overlay.BackgroundTransparency = 0.15
			overlayText.TextTransparency = 0
			overlayText.Text = "Taken.\n\nYou'll come back when the others reach somewhere safe.\n(Click to watch someone else.)"
		elseif player:GetAttribute("Downed") then
			overlay.BackgroundTransparency = 0.55
			overlayText.TextTransparency = 0
			overlayText.Text = "You're down.\nA crewmate can get you up."
		elseif overlay.BackgroundTransparency < 1 then
			overlay.BackgroundTransparency = 1
			overlayText.TextTransparency = 1
		end
	end

	if noteOpenAt then
		local character = player.Character
		local root = character and character:FindFirstChild("HumanoidRootPart")
		if not root or ((root :: BasePart).Position - noteOpenAt).Magnitude > 10 then
			Hud.closeNote()
		end
	end
end

function Hud.start()
	build()
	RunService.RenderStepped:Connect(update)
end

return Hud
]=] },
	{ service = {"StarterPlayer", "StarterPlayerScripts"}, path = {"AshgroveClient", "Torch"}, class = "ModuleScript", source = [=[
--[[
	Torch: the player's own torch, drawn locally so it follows the camera
	without lag (the server's copy on your head, which everyone else sees,
	is hidden on your screen). Also reports to the server:
	  - where you're looking, ten times a second (the torch beam that
	    monsters react to)
	  - each left click with a tool out (your gun): monsters hear the shot,
	    and Shots uses the ray to tell which body part you hit.
]]

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")

local Shared = ReplicatedStorage:WaitForChild("Ashgrove")
local Config = require(Shared:WaitForChild("Config"))
local Net = require(Shared:WaitForChild("Net"))

local player = Players.LocalPlayer

local Torch = {}

function Torch.start()
	local torch = Instance.new("Part")
	torch.Name = "AshLocalTorch"
	torch.Anchored = true
	torch.CanCollide = false
	torch.CanQuery = false
	torch.CanTouch = false
	torch.Transparency = 1
	torch.Size = Vector3.one * 0.2
	local light = Instance.new("SpotLight")
	light.Angle = Config.flashlight.angle
	light.Range = Config.flashlight.range
	light.Brightness = Config.flashlight.brightness
	light.Color = Color3.fromRGB(255, 240, 220)
	light.Shadows = true
	light.Face = Enum.NormalId.Front
	light.Enabled = false
	light.Parent = torch
	torch.Parent = workspace.CurrentCamera

	RunService:BindToRenderStep("AshgroveTorch", Enum.RenderPriority.Camera.Value + 1, function()
		local camera = workspace.CurrentCamera
		if torch.Parent ~= camera then
			torch.Parent = camera
		end
		torch.CFrame = camera.CFrame * CFrame.new(0.4, -0.5, 0)
		light.Enabled = player:GetAttribute("LightOn") == true
		local character = player.Character
		local head = character and character:FindFirstChild("Head")
		local attachment = head and head:FindFirstChild("AshFlashlight")
		local serverLight = attachment and attachment:FindFirstChild("AshFlashlight")
		if serverLight and serverLight:IsA("SpotLight") then
			serverLight.Enabled = false
		end
	end)

	local lastClick = 0
	UserInputService.InputBegan:Connect(function(input, processed)
		if processed or input.UserInputType ~= Enum.UserInputType.MouseButton1 then
			return
		end
		local character = player.Character
		if not character or not character:FindFirstChildOfClass("Tool") then
			return
		end
		local now = os.clock()
		if now - lastClick < 0.1 then
			return
		end
		lastClick = now
		local camera = workspace.CurrentCamera
		Net.event("Shot"):FireServer(camera.CFrame.Position, camera.CFrame.LookVector)
	end)

	task.spawn(function()
		local aimRemote = Net.unreliable("Aim")
		while true do
			task.wait(0.1)
			aimRemote:FireServer(workspace.CurrentCamera.CFrame.LookVector)
		end
	end)
end

return Torch
]=] },
}

local function child(parent: Instance, name: string): Instance
	local found = parent:FindFirstChild(name)
	assert(found, `[Ashgrove] expected {parent:GetFullName()}.{name} (paste the parts in order, starting from part 1)`)
	return found :: Instance
end

local function serviceAt(names: { string }): Instance
	local node: Instance = game:GetService(names[1])
	for i = 2, #names do
		node = child(node, names[i])
	end
	return node
end

local function install()
	local ChangeHistoryService = game:GetService("ChangeHistoryService")
	local ok, recording = pcall(function()
		return ChangeHistoryService:TryBeginRecording("Install Ashgrove House")
	end)
	if not ok then
		recording = nil
	end

	-- Remove older installs first.
	if REMOVE_OLD then
		for _, r in ROOTS do
			local old = serviceAt(r.service):FindFirstChild(r.name)
			if old then
				old:Destroy()
			end
		end
	end

	for _, f in FILES do
		local parent = serviceAt(f.service)
		for i = 1, #f.path - 1 do
			parent = child(parent, f.path[i])
		end
		local existing = parent:FindFirstChild(f.path[#f.path])
		if existing then
			existing:Destroy()
		end
		local inst = Instance.new(f.class)
		inst.Name = f.path[#f.path]
		if f.source then
			(inst :: any).Source = f.source
		end
		inst.Parent = parent
	end

	if FINISH then
		for _, name in { "Baseplate", "SpawnLocation" } do
			local leftover = workspace:FindFirstChild(name)
			if leftover and leftover:IsA("BasePart") then
				leftover:Destroy()
			end
		end
		if not workspace:FindFirstChild("AshgroveHouse") then
			require(game:GetService("ServerScriptService").Ashgrove.House).build()
		end
	end

	if recording then
		pcall(function()
			ChangeHistoryService:FinishRecording(recording, Enum.FinishRecordingOperation.Commit)
		end)
	end
	print(DONE_MESSAGE)
end

if plugin then
	local toolbar = plugin:CreateToolbar("Ashgrove")
	local button = toolbar:CreateButton("Install", "Install or update Ashgrove House in this place", "")
	button.ClickableWhenViewportHidden = true
	button.Click:Connect(install)
else
	install()
end
